window.DYNASTY_DATA = [
  {"key": "dawn", "title": "两河与尼罗河的黎明", "badge": "青铜早期", "fromYear": -3500, "toYear": -1650, "focusYear": -2334, "tint": "#b8952f", "seat": "乌鲁克 · 乌尔 · 巴比伦", "summary": "两河南部的神庙城市（乌鲁克、乌尔、尼普尔）发明了楔形文字与官僚会计，萨尔贡建立阿卡德帝国，乌尔第三王朝与伊辛-拉尔萨相继而兴，最后由汉谟拉比统一两河并把马尔杜克推为全国主神。同一时期埃及由早王朝走向金字塔时代，迦南与腓尼基的沿海城邦（比布鲁斯等）承担木材与铜的转口。这一千年奠定了后来赫梯、亚述与巴比伦所继承的文字、法律与神庙制度。", "sourceFiles": ["dawn"], "phases": [{"until": -3000, "snap": "s_sumer_dawn", "overview": "前 3000 年 · 苏美尔城邦时代：乌鲁克、乌尔、尼普尔等神庙城市兴起，楔形文字、轮与青铜在此出现，两河南部城邦林立。"}, {"until": -2334, "snap": "s_akkad_empire", "overview": "前 2334 年 · 阿卡德统一：萨尔贡一世征服诸城邦，建立美索不达米亚第一个帝国，阿卡德语成为官方语言。"}, {"until": -2112, "snap": "s_ur_third", "overview": "前 2112 年 · 乌尔第三王朝：乌尔纳姆重建统一，颁布现存最早的法典之一，神庙与贡赋体系高度官僚化。"}, {"until": -1900, "snap": "s_isin_larsa", "overview": "前 1900 年 · 伊辛与拉尔萨并立：乌尔第三王朝崩溃后阿摩利诸王朝分据，巴比伦尚是其中不起眼的一支。"}, {"until": -1750, "snap": "s_hammurabi", "overview": "前 1750 年 · 汉谟拉比统一两河：汉谟拉比击败拉尔萨与马里，法典刻石传世，巴比伦的马尔杜克升为全国主神。"}], "milestones": [{"year": -3200, "headline": "乌鲁克的楔形文字与城市革命", "site": "乌鲁克", "coord": [45.64, 31.32], "detail": "乌鲁克（瓦尔卡）在捷姆迭特那色时期扩张为近 100 公顷的城市，出现塔庙（Eanna 与 Anu 区）、圆柱印章、记账泥板与最早的数字符号；文字从经济会计中产生，是世界上最早的书写系统。", "source": "《剑桥古代史》卷 1（Uruk 期）/ 乌鲁克-瓦尔卡发掘报告（德国考古研究所）"}, {"year": -2600, "headline": "乌尔王陵与早期王权", "site": "乌尔", "coord": [46.1, 30.96], "detail": "伍莱（Leonard Woolley）1920—30 年代在乌尔发掘的王陵（约前 2600—前 2500）出土金器、青金石、镶饰军旗与人殉墓室，显示早期城邦的王权与远程贸易网络已相当发达。", "source": "Woolley《Ur Excavations》卷 2（Royal Cemetery）"}, {"year": -2334, "headline": "萨尔贡建立阿卡德帝国", "site": "阿卡德", "coord": [44.3, 33.1], "detail": "萨尔贡（Šarru-kīn）以阿卡德城为中心击败乌鲁克与乌玛诸邦，建立跨族群的帝国，以阿卡德语取代苏美尔语为行政语言，并留下「天下四方之王」的头衔；阿卡德城位置至今未确认。", "source": "《剑桥古代史》卷 1 / 阿卡德时期铭文（Sargon 传说与 Naram-Sin 铭文）"}, {"year": -2112, "headline": "乌尔第三王朝与乌尔纳姆法典", "site": "乌尔", "coord": [46.1, 30.96], "detail": "乌尔纳姆驱逐古提人、统一南部两河，颁布现存最早的成文法典（乌尔纳姆法典，早于汉谟拉比约三百年）；王朝以「阿卡德与苏美尔之王」自居，留下数十万件行政与经济泥板。", "source": "《剑桥古代史》卷 1 / 乌尔纳姆法典泥板（伊斯坦布尔、宾大藏）"}, {"year": -1894, "headline": "巴比伦第一王朝崛起", "site": "巴比伦", "coord": [44.42, 32.54], "detail": "阿摩利人苏穆阿布姆（Sumu-abum）在巴比伦建城立朝，此时巴比伦只是伊辛、拉尔萨、埃什努那之间的小邦；此后一个半世纪逐步扩张，成为两河南部的中心。", "source": "《剑桥古代史》卷 1 / 巴比伦王名表（Babylonian King List A）"}, {"year": -1750, "headline": "汉谟拉比法典刻石", "site": "巴比伦", "coord": [44.42, 32.54], "detail": "汉谟拉比击败拉尔萨与马里统一两河，把判例法刻在 2.25 米高的闪长岩石碑上（1901 年于苏萨发现，今卢浮宫），顶部为汉谟拉比受权于太阳神沙马什的浮雕；马尔杜克由此升为全国主神。", "source": "汉谟拉比法典石碑（Louvre Sb 8）/《剑桥古代史》卷 1"}, {"year": -1650, "headline": "赫梯登上安纳托利亚舞台", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "哈图西里一世定都哈图沙，赫梯王国成形；此后一个半世纪内赫梯南下叙利亚、并前 1595 年劫掠巴比伦，从安纳托利亚的区域势力变为近东强权。", "source": "Bryce《赫梯王国》/ 哈图沙档案（Boğazköy 泥板）"}], "settlements": [{"ancient": "乌鲁克", "modern": "瓦尔卡（伊拉克）", "coord": [45.64, 31.32], "isCapital": true, "remark": "前 4 千年最大的城市，楔形文字发源地", "source": "Uruk-Warka 发掘报告（德国考古研究所）"}, {"ancient": "乌尔", "modern": "乌尔遗址（伊拉克）", "coord": [46.1, 30.96], "remark": "南纳神庙与乌尔王陵", "source": "Woolley《Ur Excavations》卷 2 / 乌尔纳姆法典"}, {"ancient": "尼普尔", "modern": "努法尔（伊拉克）", "coord": [45.23, 32.13], "remark": "恩利尔神庙，两河宗教中心", "source": "Nippur 发掘报告（宾夕法尼亚大学）"}, {"ancient": "巴比伦", "modern": "巴比伦遗址（伊拉克）", "coord": [44.42, 32.54], "remark": "前 18 世纪起为巴比伦尼亚核心", "source": "Babylon 发掘（Koldewey）/ 汉谟拉比法典石碑"}, {"ancient": "孟菲斯", "modern": "孟菲斯遗址（埃及）", "coord": [31.25, 29.85], "remark": "埃及早王朝首都", "source": "Memphis 发掘报告（埃及文物最高委员会）"}, {"ancient": "比布鲁斯", "modern": "朱拜勒（黎巴嫩）", "coord": [35.65, 34.12], "remark": "腓尼基最古老的港口，木材转口", "source": "《剑桥古代史》卷 1 / 《牛津古埃及史》"}, {"ancient": "埃勃拉", "modern": "特尔马尔迪赫（叙利亚）", "coord": [36.8, 35.8], "remark": "前 3 千年的叙利亚商队王国", "source": "Ebla 档案（Matthiah 等）/ 罗马大学发掘报告"}, {"ancient": "哈图沙", "modern": "博阿兹卡莱", "coord": [34.62, 40.02], "remark": "前 17 世纪成为赫梯都城", "source": "Boğazköy（哈图沙）发掘报告 / Bryce《赫梯王国》"}]},
  {"key": "hittite", "title": "赫梯时代", "badge": "赫梯", "fromYear": -1650, "toYear": -1180, "focusYear": -1350, "tint": "#a8452f", "seat": "哈图沙（博阿兹卡莱）", "summary": "哈图西里一世定都哈图沙，穆尔西里一世前 1595 年劫掠巴比伦；苏庇路里乌玛一世（前 1344—前 1322）击溃米坦尼，与埃及拉美西斯二世在卡迭石对峙并于前 1259 年缔结和约。帝国核心在安纳托利亚中部，兼控北叙利亚。前 1180 年前后随“青铜时代崩溃”瓦解。", "sourceFiles": ["hittite"], "phases": [{"until": -1650, "snap": "s_hittite_old", "overview": "前 1650 年 · 赫梯古王国：哈图西里一世定都哈图沙，赫梯登上安纳托利亚舞台；阿尔扎瓦诸国据西部。"}, {"until": -1600, "snap": "s_hittite_early", "overview": "前 1600 年 · 赫梯早期扩张：穆尔西里一世南征叙利亚，前 1595 年劫掠巴比伦后因内乱退兵。"}, {"until": -1595, "snap": "s_babylon_sack", "overview": "前 1595 年 · 穆尔西里一世灭古巴比伦：穆尔西里一世沿幼发拉底南下攻陷巴比伦，古巴比伦第一王朝终结；赫梯因后方空虚随即内乱。"}, {"until": -1500, "snap": "s_hittite_mid", "overview": "前 1500 年 · 赫梯中王国：帝国中衰，卡什卡诸部南下侵扰北境，米坦尼在叙利亚称雄。"}, {"until": -1400, "snap": "s_hittite_recovery", "overview": "前 1400 年 · 赫梯复兴：图特哈里二世重整国力，重新插手叙利亚，与米坦尼、埃及三方角力。"}, {"until": -1350, "snap": "s_hittite_empire", "overview": "前 1350 年 · 赫梯帝国鼎盛：苏庇路里乌玛一世击溃米坦尼，赫梯成为近东两大强权之一。"}, {"until": -1295, "snap": "s_hittite_late_peak", "overview": "前 1295 年 · 穆瓦塔里二世迁都：迁都塔胡恩塔萨（今土耳其南部），与埃及在叙利亚长期对峙。"}, {"until": -1274, "snap": "s_qadesh", "overview": "前 1274 年 · 卡迭石之战：穆瓦塔里二世与埃及拉美西斯二世在奥龙特斯河畔会战，前 1259 年缔和。"}, {"until": -1230, "snap": "s_hittite_twilight", "overview": "前 1230 年 · 赫梯晚期：图特哈里四世应对海上民族与西部卡什卡的压力，帝国衰落但尚未瓦解。"}, {"until": -1180, "snap": "s_bronze_collapse", "overview": "前 1180 年 · 青铜时代崩溃：海上民族与系统性崩溃终结赫梯帝国，安纳托利亚进入黑暗时代。"}], "milestones": [{"year": -1650, "headline": "哈图西里一世定都哈图沙，赫梯王国成形", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "哈图西里一世（约前 1650—前 1620 在位）把都城从库沙拉迁到哈图沙（今博阿兹卡莱），统一安纳托利亚中部。赫梯由此从若干城邦联盟变成中央集权的王国，并继承阿卡德-亚述式书吏传统，留下印欧语系最早的大宗文献档案。", "source": "Bryce《赫梯王国》"}, {"year": -1620, "headline": "赫梯南下阿勒颇与幼发拉底", "site": "阿勒颇", "coord": [37.16, 36.2], "detail": "哈图西里一世南下攻阿勒颇与幼发拉底沿线，确立赫梯在叙利亚的第一次扩张，并带回巴比伦的战利品与书吏传统。", "source": "赫梯泥板档案"}, {"year": -1610, "headline": "《铁列平诏令》确立王位继承法", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "铁列平颁布诏令，规定王位只能由王室成员按次序继承，并设贵族议事会审理命案。这是赫梯最早的「宪法性」文献，试图终结此前频繁的宫廷谋杀。", "source": "《铁列平诏令》"}, {"year": -1595, "headline": "穆尔西里一世远征巴比伦，古巴比伦灭亡", "site": "巴比伦", "coord": [44.42, 32.54], "detail": "穆尔西里一世沿幼发拉底河南下，攻陷巴比伦、推翻古巴比伦第一王朝（汉谟拉比之后的末代）。因远征过远、后方空虚，他回国后即被刺杀，赫梯进入「黑暗期」，巴比伦则被加喜特人占据。", "source": "《赫梯诏令》与巴比伦编年史"}, {"year": -1500, "headline": "卡什卡诸部南下侵扰北境", "site": "卡什卡山地", "coord": [36.5, 41.0], "detail": "山地部族卡什卡趁赫梯中衰南下，反复劫掠北境，甚至威胁哈图沙；赫梯以筑垒、迁徙与季节征讨应对，成为长期边患。", "source": "赫梯档案"}, {"year": -1440, "headline": "图特哈里二世重建帝国", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "中王国衰落后，图特哈里二世修复哈图沙城墙、重建对卡什卡与阿尔扎瓦的控制，为苏庇路里乌玛一世的扩张奠定基础。", "source": "赫梯泥板档案"}, {"year": -1344, "headline": "苏庇路里乌玛一世即位", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "他以军事与外交并用，先平西部阿尔扎瓦，再南下肢解米坦尼，把赫梯推上近东一等强国；其子穆尔西里二世延续扩张。", "source": "赫梯《苏庇路里乌玛功业录》"}, {"year": -1330, "headline": "阿马尔那书信时代", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "埃及、赫梯、米坦尼、巴比伦之间的泥板外交书信（阿马尔那文书）是青铜时代国际关系的一手材料，内容涉及王朝联姻、礼物交换与逃犯引渡。", "source": "阿马尔那书信 / 赫梯档案"}, {"year": -1295, "headline": "穆瓦塔里二世南迁都城塔尔胡恩塔萨", "site": "塔尔胡恩塔萨", "coord": [36.93, 37.58], "detail": "为贴近叙利亚前线，穆瓦塔里二世把政治中心南迁到塔尔胡恩塔萨；哈图沙仍为宗教中心，卡迭石之战即由此调度。", "source": "赫梯档案与考古"}, {"year": -1274, "headline": "卡迭石之战：穆瓦塔里二世与拉美西斯二世对峙", "site": "卡迭石", "coord": [36.52, 34.56], "detail": "埃及法老拉美西斯二世北征叙利亚，与赫梯国王穆瓦塔里二世在奥龙特斯河畔的卡迭石相遇。双方都宣称获胜：埃及的战报刻在神庙墙上，赫梯的版本存于泥板。此役是古代规模最大的战车会战之一（双方各约 2 万—3 万人）。", "source": "埃及《卡迭石铭文》/ 赫梯泥板"}, {"year": -1259, "headline": "《卡迭石和约》：已知最早的国际和平条约", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "十六年后，哈图西里三世与拉美西斯二世以「兄弟」相称缔结和约，划定势力范围并规定引渡逃犯。原本刻在银板上（已佚），埃及卡尔纳克与赫梯档案各存一份；今联合国总部陈列其复制件，被称为「最早的和平条约」。", "source": "埃及与赫梯双语文本"}, {"year": -1258, "headline": "沿海劫掠与「海上民族」前夜", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "赫梯档案记载 Ahhiyawa 与沿海劫掠活动，塞浦路斯（阿拉西亚）与南岸最先受冲击；这是 1180 年大崩溃前数十年的预警信号。", "source": "赫梯泥板 / 乌加里特文书"}, {"year": -1190, "headline": "哈图沙的毁灭层", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "考古在哈图沙发现火烧与弃城层，与青铜时代崩溃同期。赫梯书吏传统中断，城市荒废三千年，直到 19 世纪被重新发现、20 世纪由德国考古队系统发掘。", "source": "博阿兹卡莱发掘报告"}, {"year": -1180, "headline": "青铜时代崩溃，赫梯帝国解体", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "东地中海在数十年间同时崩溃：海上民族袭掠沿海、迈锡尼与乌加里特毁城、埃及退回尼罗河。赫梯首都哈图沙被焚，中央政权消失，书写传统中断，安纳托利亚进入约四百年的「黑暗时代」。", "source": "《剑桥古代史》卷 II.2"}], "settlements": [{"ancient": "哈图沙", "modern": "博阿兹卡莱", "coord": [34.62, 40.02], "isCapital": true, "remark": "赫梯都城，世界遗产", "source": "Boğazköy（哈图沙）发掘报告 / Bryce《赫梯王国》"}, {"ancient": "巴比伦", "modern": "巴比伦遗址（伊拉克）", "coord": [44.42, 32.54], "remark": "古巴比伦都城，前 1595 年被赫梯攻陷", "source": "Babylon 发掘（Koldewey）/ 汉谟拉比法典石碑"}, {"ancient": "沙皮努瓦", "modern": "舒沙特（Çorum）", "coord": [34.95, 40.55], "isCapital": false, "remark": "赫梯宗教中心", "source": "Boğazköy 档案与 Kayalıpınar 发掘 / Bryce"}, {"ancient": "内萨", "modern": "屈尔泰佩", "coord": [35.48, 38.73], "isCapital": false, "remark": "早期赫梯/亚述商馆", "source": "Kültepe（卡涅什）发掘报告（Tahsin Özgüç）"}, {"ancient": "卡涅什", "modern": "屈尔泰佩", "coord": [35.48, 38.73], "isCapital": false, "source": "Kültepe 亚述商馆档案（TC III）/ Özgüç"}, {"ancient": "阿尔扎瓦", "modern": "以弗所一带", "coord": [27.34, 37.94], "isCapital": false, "remark": "赫梯文献中的西部同盟", "source": "Bryce《赫梯王国》/ 土耳其文化遗产名录"}, {"ancient": "米拉", "modern": "米拉斯", "coord": [27.78, 37.31], "isCapital": false, "source": "Bryce《赫梯王国》/ 土耳其文化遗产名录"}, {"ancient": "塔尔胡恩塔萨", "modern": "卡拉曼马拉什", "coord": [36.93, 37.58], "isCapital": false, "source": "Yalburt 与 Gavurkale 铭文 / Bryce"}, {"ancient": "阿勒颇", "modern": "阿勒颇", "coord": [37.16, 36.2], "isCapital": false, "remark": "赫梯与埃及争夺的北叙利亚枢纽", "source": "《剑桥伊斯兰史》卷 1 / Ibn al-ʿAdim"}, {"ancient": "孟菲斯", "modern": "孟菲斯遗址（埃及）", "coord": [31.25, 29.85], "remark": "埃及新王国北都，卡迭石之战的一方", "source": "Memphis 发掘报告（埃及文物最高委员会）"}, {"ancient": "底比斯", "modern": "卢克索（埃及）", "coord": [32.65, 25.7], "remark": "埃及新王国宗教首都（图外以南）", "source": "《牛津古埃及史》/ 底比斯墓葬测绘（MMA）"}, {"ancient": "尼尼微", "modern": "摩苏尔附近（伊拉克）", "coord": [43.15, 36.36], "remark": "中亚述都城", "source": "Nineveh 发掘报告（Layard 等）/《剑桥古代史》卷 3"}, {"ancient": "乌尔", "modern": "乌尔遗址（伊拉克）", "coord": [46.1, 30.96], "remark": "两河南部圣城", "source": "Woolley《Ur Excavations》卷 2 / 乌尔纳姆法典"}]},
  {"key": "post_hittite", "title": "铁器早期", "badge": "黑暗时代", "fromYear": -1180, "toYear": -660, "focusYear": -900, "tint": "#8a5a2b", "seat": "戈尔迪乌姆 · 图什帕 · 卡赫美士", "summary": "帝国崩溃后安纳托利亚进入多中心时代：弗里吉亚人据中西部（前 8 世纪以戈尔迪乌姆为都），乌拉尔图在东部凡湖崛起与亚述争雄，东南部为卢维人的新赫梯城邦（卡赫美士、马尔丁），西部爱奥尼亚希腊城邦兴起。前 696/695 年辛梅里安人攻灭弗里吉亚。", "sourceFiles": ["post_hittite"], "phases": [{"until": -1100, "snap": "s_post_collapse", "overview": "前 1100 年 · 崩溃之后：新赫梯诸邦在东南延续，弗里吉亚人据中西部，安纳托利亚无统一强权。"}, {"until": -1000, "snap": "s_dark_age", "overview": "前 1000 年 · 铁器早期：弗里吉亚人、新赫梯诸邦与乌拉尔图在废墟上兴起，东部进入铁器时代。"}, {"until": -950, "snap": "s_phrygia_rise", "overview": "前 950 年 · 弗里吉亚兴起：戈尔迪乌姆成为中西部中心，乌拉尔图在凡湖成型。"}, {"until": -860, "snap": "s_urartu_rise", "overview": "前 860 年 · 乌拉尔图崛起：图什帕（凡城）为都，乌拉尔图与亚述争雄东部高原。"}, {"until": -800, "snap": "s_assyria_pressure", "overview": "前 800 年 · 亚述西进：提格拉特帕拉沙尔三世以降，亚述逼近叙利亚与东南安纳托利亚。"}, {"until": -750, "snap": "s_phrygia_peak", "overview": "前 750 年 · 弗里吉亚鼎盛：戈尔迪乌姆的迈达斯王统辖中西部，爱奥尼亚希腊城邦沿海兴起。"}, {"until": -700, "snap": "s_urartu_peak", "overview": "前 700 年 · 乌拉尔图鼎盛：阿尔吉什提一世扩张至亚美尼亚高原，与亚述争夺东部霸权。"}, {"until": -695, "snap": "s_cimmerian", "overview": "前 695 年 · 辛梅里安之乱：辛梅里安人自高加索南下攻灭弗里吉亚，吕底亚开始崛起。"}], "milestones": [{"year": -1180, "headline": "帝国崩溃，安纳托利亚进入多中心时代", "site": "哈图沙", "coord": [34.62, 40.02], "detail": "赫梯中央政权消失后，安纳托利亚不再有单一强权：东南部由卢维人的「新赫梯」城邦（卡赫美士、马尔丁）延续赫梯文化，中西部为弗里吉亚人，东部高原为乌拉尔图与亚美尼亚部落。这段空白期主要靠考古地层而非文献复原。", "source": "Bryce《新赫梯诸王国》"}, {"year": -1150, "headline": "弗里吉亚人进入安纳托利亚", "site": "戈尔迪乌姆", "coord": [31.98, 39.65], "detail": "希腊传统认为弗里吉亚人自巴尔干迁入，考古显示其陶器与墓葬在公元前 12—11 世纪突然出现于中西部，与赫梯崩溃的时间吻合。", "source": "《剑桥古代史》卷 II.2"}, {"year": -1000, "headline": "铁器技术随帝国崩溃扩散", "site": "卡赫美士", "coord": [38.02, 36.83], "detail": "赫梯长期垄断的冶铁与锻打技术随帝国解体向外流散，安纳托利亚成为铁器早期扩散的核心区之一，农具与武器成本随之下降。", "source": "冶金考古研究"}, {"year": -930, "headline": "草原压力与筑垒化定居", "site": "锡瓦斯", "coord": [37.02, 39.75], "detail": "高加索与黑海草原的游牧压力加剧，东部安纳托利亚出现密集的筑垒定居点与山地避难所，村落网络比青铜时代更分散。", "source": "安纳托利亚考古调查"}, {"year": -900, "headline": "乌拉尔图以图什帕（凡城）为都，与亚述争雄", "site": "图什帕", "coord": [43.38, 38.49], "detail": "乌拉尔图（亚述语称 Urartu，《圣经》中的亚拉腊）在凡湖以东兴起，以图什帕（今凡城）为都，凭山地水利与冶金立国。它与亚述争夺东部商路与铁矿，留下了大量楔形文字岩刻与运河遗迹。", "source": "Zimansky《古代乌拉尔图》"}, {"year": -850, "headline": "乌拉尔图的阿尔吉什提一世", "site": "图什帕", "coord": [43.38, 38.49], "detail": "阿尔吉什提一世把乌拉尔图扩张至亚美尼亚高原与库拉河，留下埃里温附近的「阿尔吉什提碑」，是乌拉尔图最盛期的铭文证据。", "source": "乌拉尔图楔形文字铭文"}, {"year": -830, "headline": "亚述驿道与贡赋体系", "site": "迪亚巴克尔", "coord": [40.23, 37.91], "detail": "亚述在东南安纳托利亚设驿道与行省，向当地小邦征收铁、马匹与木料，把高原经济纳入两河流域的帝国体系。", "source": "亚述行政文书"}, {"year": -800, "headline": "弗里吉亚戈尔迪乌姆的迈达斯王，与希腊德尔斐神谕相关", "site": "戈尔迪乌姆", "coord": [31.98, 39.65], "detail": "希腊传统把戈尔迪乌姆的国王称为「迈达斯」（Midas），与德尔斐神谕和「点石成金」传说相关。考古在戈尔迪乌姆发现大型木构陵墓与希腊进口陶器，说明弗里吉亚与爱琴海世界贸易密切。", "source": "戈尔迪乌姆发掘报告"}, {"year": -760, "headline": "迈达斯向德尔斐献金座", "site": "戈尔迪乌姆", "coord": [31.98, 39.65], "detail": "迈达斯王向德尔斐阿波罗神庙献上宝座，是安纳托利亚君主首次直接介入希腊宗教中心，反映弗里吉亚与爱琴海世界的贸易与外交深度。", "source": "希罗多德 i.14"}, {"year": -730, "headline": "辛梅里安人越过高加索", "site": "锡诺普", "coord": [35.15, 42.03], "detail": "辛梅里安人自高加索南下，先冲击乌拉尔图，再进入安纳托利亚中部，成为亚述与吕底亚共同的头号边患，也促成了安纳托利亚各邦的军事化。", "source": "亚述王室铭文"}, {"year": -717, "headline": "亚述萨尔贡二世灭卡赫美士，新赫梯诸邦终", "site": "卡赫美士", "coord": [38.02, 36.83], "detail": "亚述国王萨尔贡二世攻陷卡赫美士，终结最后一个重要的新赫梯城邦。亚述把东南安纳托利亚划为行省，赫梯-卢维的书吏与艺术传统随之被亚述吸收。萨爾贡二世随后建都杜尔-沙鲁金（今霍尔萨巴德）。", "source": "《剑桥古代史》卷 III.1"}, {"year": -710, "headline": "迈达斯与亚述的角力", "site": "戈尔迪乌姆", "coord": [31.98, 39.65], "detail": "亚述王萨尔贡二世记载与「米塔」（Mita，即迈达斯）争夺东部商路；此后弗里吉亚被辛梅里安摧毁，戈尔迪乌姆的大墓成为其文明的最后遗存。", "source": "萨尔贡二世铭文"}, {"year": -696, "headline": "辛梅里安人攻灭弗里吉亚", "site": "戈尔迪乌姆", "coord": [31.98, 39.65], "detail": "辛梅里安人自高加索南下，攻破戈尔迪乌姆，弗里吉亚王国崩溃。希腊史料记迈达斯王饮牛血自尽。此后吕底亚接替弗里吉亚成为西部霸主，辛梅里安人又被吕底亚逐出。", "source": "希罗多德《历史》i.15"}, {"year": -676, "headline": "乌拉尔图终被米底与斯基泰所灭", "site": "图什帕", "coord": [43.38, 38.49], "detail": "乌拉尔图在斯基泰与米底夹击下瓦解，凡城一带归米底；其水利工程、青铜工艺与岩刻传统被后继的亚美尼亚与波斯文化吸收。", "source": "希罗多德 / 巴比伦编年史"}], "settlements": [{"ancient": "戈尔迪乌姆", "modern": "波拉特勒", "coord": [31.98, 39.65], "isCapital": true, "remark": "弗里吉亚都城", "source": "Gordion 发掘报告（宾夕法尼亚大学）/《剑桥古代史》卷 3"}, {"ancient": "图什帕", "modern": "凡城", "coord": [43.38, 38.49], "isCapital": true, "remark": "乌拉尔图都城", "source": "凡城城堡与 Kef Kalesi 铭文 / Zimansky《古代乌拉尔图》"}, {"ancient": "卡赫美士", "modern": "杰拉布卢斯", "coord": [38.02, 36.83], "isCapital": false, "source": "Carchemish 发掘报告（Hogarth/Woolley）/ Bryce"}, {"ancient": "马尔丁", "modern": "马尔丁", "coord": [40.74, 37.31], "isCapital": false, "source": "《剑桥古代史》卷 3 / 土耳其文化遗产名录"}, {"ancient": "米利都", "modern": "巴拉特", "coord": [27.28, 37.53], "isCapital": false, "remark": "爱奥尼亚希腊城邦", "source": "Milet 发掘报告（柏林）/ 希罗多德 v"}, {"ancient": "士麦那", "modern": "伊兹密尔", "coord": [27.14, 38.42], "isCapital": false, "source": "《剑桥古代史》卷 3 / 土耳其文化遗产名录"}, {"ancient": "锡诺普", "modern": "锡诺普", "coord": [35.15, 42.03], "isCapital": false, "remark": "黑海希腊殖民城", "source": "《剑桥古代史》卷 3 / 土耳其文化遗产名录"}, {"ancient": "大马士革", "modern": "大马士革（叙利亚）", "coord": [36.29, 33.51], "remark": "阿拉米大马士革王国都城", "source": "《剑桥伊斯兰史》卷 1 / Ibn ʿAsākir《大马士革史》"}, {"ancient": "推罗", "modern": "苏尔（黎巴嫩）", "coord": [35.2, 33.27], "remark": "腓尼基殖民母邦，前 9 世纪建立迦太基", "source": "希罗多德 ii.44 / 亚历山大的推罗围城（阿里安 ii）"}, {"ancient": "尼尼微", "modern": "摩苏尔附近（伊拉克）", "coord": [43.15, 36.36], "remark": "亚述帝国晚期都城", "source": "Nineveh 发掘报告（Layard 等）/《剑桥古代史》卷 3"}]},
  {"key": "lydia", "title": "吕底亚与东方诸国", "badge": "吕底亚", "fromYear": -660, "toYear": -546, "focusYear": -600, "tint": "#b8892f", "seat": "萨第斯", "summary": "辛梅里安人退去后吕底亚以萨第斯为都称霸安纳托利亚西部，前 7 世纪铸造西方最早的钱币；与米底以哈里斯河（克孜勒河）为界。东部乌拉尔图衰落，亚述于前 612 年亡于米底与新巴比伦，小亚细亚东部归米底；本都、卡帕多细亚诸小邦与希腊殖民城邦（锡诺普、特拉佩祖斯）并存。", "sourceFiles": ["lydia"], "phases": [{"until": -650, "snap": "s_lydia_rise", "overview": "前 650 年 · 吕底亚崛起：古革斯王朝据萨第斯，与亚述结盟抗辛梅里安；小亚细亚最早的钱币出现。"}, {"until": -620, "snap": "s_assyria_fall", "overview": "前 620 年 · 亚述灭亡：尼尼微陷落，米底与新巴比伦瓜分亚述；吕底亚趁势西进。"}, {"until": -585, "snap": "s_halys_battle", "overview": "前 585 年 · 哈里斯河之战：吕底亚与米底以克孜勒河为界，日食之年双方罢兵。"}, {"until": -546, "snap": "s_cyrus_conquest", "overview": "前 546 年 · 居鲁士灭吕底亚：萨第斯陷落，安纳托利亚西部并入阿契美尼德帝国。"}], "milestones": [{"year": -680, "headline": "古革斯建立吕底亚梅尔姆纳德王朝", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "古革斯（Gyges）刺杀坎道列斯夺取王位，建立梅尔姆纳德王朝，都萨第斯。他派使者赴亚述求援对抗辛梅里安人，是安纳托利亚西部君主首次与两河强权直接交涉；其名字见于亚述泥板（Gugu）。", "source": "希罗多德 i.8—14 / 亚述泥板"}, {"year": -660, "headline": "吕底亚与爱奥尼亚希腊城邦的长期战争", "site": "米利都", "coord": [27.28, 37.53], "detail": "古革斯与阿尔迪斯进攻爱奥尼亚诸城，围攻米利都十余年未克；双方后来转为雇佣与贸易关系，吕底亚的骑兵与希腊的重装步兵互相补充。", "source": "希罗多德 i.14—22"}, {"year": -640, "headline": "吕底亚骑兵东进卡帕多细亚", "site": "卡帕多细亚", "coord": [35.5, 38.7], "detail": "吕底亚以骑射与重装骑兵称雄，向东推进至哈里斯河一线，与米底形成长期对峙，东部诸小邦夹在两者之间。", "source": "希罗多德 i.73—74"}, {"year": -630, "headline": "辛梅里安人攻掠萨第斯，古革斯战死", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "辛梅里安人破萨第斯，古革斯战死，其子阿尔迪斯继位。吕底亚一度向亚述称臣求援，最终在前 6 世纪初把辛梅里安人逐出安纳托利亚。这场战乱让萨第斯在考古地层中留下明显的破坏层。", "source": "希罗多德 i.15—16"}, {"year": -610, "headline": "小亚细亚最早的钱币（琥珀金）在吕底亚流通", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "吕底亚铸造西方最早的标准钱币：天然金银合金（electrum）的「斯塔特」，一面有狮子头印记。以弗所阿耳忒弥斯神庙遗址出土的早期钱币窖藏是直接证据。货币化推动了爱琴海贸易与国家财政。", "source": "以弗所钱币窖藏 / 大英博物馆藏品"}, {"year": -600, "headline": "萨第斯的手工业与染坊区", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "考古在萨第斯发现染坊、作坊与商业街区，显示吕底亚宫廷财富与手工业者、希腊工匠之间的共生关系。", "source": "萨第斯发掘报告"}, {"year": -590, "headline": "萨第斯的王家坟冢与阿耳忒弥斯神庙", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "辛梅里安人撤走后萨第斯重建，出现巨型土墩王陵（tumulus，如 Bintepeler）与阿耳忒弥斯神庙，显示吕底亚王室财富与希腊工匠的结合。", "source": "萨第斯发掘报告"}, {"year": -585, "headline": "哈里斯河之战后与米底划界（日食之年）", "site": "克孜勒河", "coord": [35.0, 39.2], "detail": "吕底亚与米底争夺东部，哈里斯河（今克孜勒河）畔会战时恰逢日全食（天文学可精确推算为前 585 年 5 月 28 日），双方视为天谴而罢兵，以河为界。这是史上第一次有确切日期的战役，也标定希罗多德的年代学。", "source": "希罗多德 i.74"}, {"year": -580, "headline": "吕底亚与米利都的互不侵犯条约", "site": "米利都", "coord": [27.28, 37.53], "detail": "吕底亚与米利都达成和平与雇佣协议：米利都获得内陆市场，吕底亚获得海军技术与外交通道，是「强国—城邦」共生的典型。", "source": "希罗多德 i.22"}, {"year": -560, "headline": "克罗伊斯即位与德尔斐献礼", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "克罗伊斯征服爱奥尼亚诸城、向德尔斐阿波罗神庙献厚礼并与斯巴达结盟，是「富如克罗伊斯」典故的由来，也是吕底亚外交的巅峰。", "source": "希罗多德 i.26—56"}, {"year": -550, "headline": "居鲁士遣使与斯巴达的迟疑", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "居鲁士遣使要求吕底亚臣服，克罗伊斯转向斯巴达求援；斯巴达援军未及赶赴，萨第斯在两周内陷落。", "source": "希罗多德 i.69—81"}, {"year": -547, "headline": "居鲁士二世攻陷萨第斯，吕底亚亡", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "居鲁士二世围攻萨第斯十四天后破城，吕底亚国王克里苏斯（《圣经》中的 Croesus）被俘。吕底亚的金库与铸币技术为波斯所用，安纳托利亚西部自此成为阿契美尼德的行省（萨尔迪斯行省）。", "source": "希罗多德 i.76—84"}, {"year": -546, "headline": "帕克托罗斯河的砂金与铸币", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "吕底亚金币的原料来自帕克托罗斯河冲积砂金；波斯接管后沿用其铸币重量标准与税制，希腊世界由此进入货币经济时代。", "source": "希罗多德 / 冶金考古"}], "settlements": [{"ancient": "萨第斯", "modern": "萨尔特", "coord": [28.04, 38.48], "isCapital": true, "remark": "吕底亚都城，铸币起源地", "source": "Sardis 发掘报告（哈佛—康奈尔）/ 希罗多德 i"}, {"ancient": "以弗所", "modern": "塞尔丘克", "coord": [27.34, 37.94], "isCapital": false, "remark": "阿尔忒弥斯神庙", "source": "ÖAI 以弗所发掘报告 /《以弗所铭文集成》(IvE)"}, {"ancient": "米利都", "modern": "巴拉特", "coord": [27.28, 37.53], "isCapital": false, "remark": "泰勒斯与自然哲学", "source": "Milet 发掘报告（柏林）/ 希罗多德 v"}, {"ancient": "普里耶涅", "modern": "普里耶涅", "coord": [27.3, 37.66], "isCapital": false, "source": "希罗多德《历史》/《剑桥古代史》卷 4"}, {"ancient": "桑索斯", "modern": "克尼克", "coord": [29.31, 36.36], "isCapital": false, "remark": "吕基亚都城", "source": "希罗多德《历史》/《剑桥古代史》卷 4"}, {"ancient": "戈尔德翁", "modern": "波拉特勒", "coord": [31.98, 39.65], "isCapital": false, "source": "希罗多德《历史》/《剑桥古代史》卷 4"}, {"ancient": "埃克巴坦那", "modern": "哈马丹", "coord": [48.52, 34.8], "isCapital": false, "remark": "米底都城", "source": "希罗多德《历史》/《剑桥古代史》卷 4"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.23, 31.78], "remark": "前 586 年第一圣殿被新巴比伦焚毁", "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}, {"ancient": "孟菲斯", "modern": "孟菲斯遗址（埃及）", "coord": [31.25, 29.85], "remark": "埃及后王朝都城之一", "source": "Memphis 发掘报告（埃及文物最高委员会）"}, {"ancient": "推罗", "modern": "苏尔（黎巴嫩）", "coord": [35.2, 33.27], "remark": "尼布甲尼撒围城十三年未克", "source": "希罗多德 ii.44 / 亚历山大的推罗围城（阿里安 ii）"}]},
  {"key": "achaemenid", "title": "阿契美尼德波斯", "badge": "波斯行省", "fromYear": -546, "toYear": -334, "focusYear": -480, "tint": "#9a5f8f", "seat": "萨尔迪斯 · 达斯基雷翁", "summary": "前 547/546 年居鲁士二世灭吕底亚，安纳托利亚并入阿契美尼德帝国，分为萨尔迪斯、赫勒斯滂弗里吉亚、卡帕多细亚、亚美尼亚等行省（satrapy）。前 499—前 493 年爱奥尼亚起义引发希波战争；前 387/386 年《大王和约》后西部希腊城邦复归波斯。前 334 年亚历山大渡海东征终结波斯统治。", "sourceFiles": ["achaemenid"], "phases": [{"until": -550, "snap": "s_cyrus_rise", "overview": "前 550 年 · 居鲁士崛起：波斯人推翻米底，居鲁士二世兵临哈里斯河，吕底亚危在旦夕。"}, {"until": -500, "snap": "s_ionian_revolt", "overview": "前 500 年 · 爱奥尼亚起义：米利都求援雅典，波斯行省体制遭受挑战，希波战争前夜。"}, {"until": -480, "snap": "s_persian_wars", "overview": "前 480 年 · 希波战争：薛西斯一世渡赫勒斯滂，萨拉米斯海战后波斯西进受阻。"}, {"until": -420, "snap": "s_persian_late", "overview": "前 420 年 · 波斯行省晚期：安纳托利亚诸行省由半独立邦君治理，波斯中央控制松弛。"}, {"until": -386, "snap": "s_kings_peace", "overview": "前 386 年 · 大王和约：《安塔尔基达斯和约》把西部希腊城邦交还波斯，阿契美尼德重控安纳托利亚。"}, {"until": -360, "snap": "s_satrap_revolt", "overview": "前 360 年 · 总督叛乱：西部总督连年叛乱（大数总督之战），为马其顿东进铺路。"}], "milestones": [{"year": -547, "headline": "居鲁士二世灭吕底亚，安纳托利亚并入波斯", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "居鲁士二世灭吕底亚后，把安纳托利亚西部编为萨尔迪斯行省，保留吕底亚的行政与铸币体系，并在萨第斯派驻总督。波斯由此获得爱琴海东岸的希腊城邦与丰厚税源。", "source": "希罗多德 i.153—160"}, {"year": -540, "headline": "大流士一世推行行省（satrapy）制度", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "大流士把帝国划为二十余行省，安纳托利亚分属萨尔迪斯、赫勒斯滂弗里吉亚、卡帕多细亚等，实行定额贡赋与定期巡查，是古代最早的大规模官僚税制之一。", "source": "希罗多德 iii.89—97"}, {"year": -520, "headline": "「王之道」与驿站系统", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "自萨第斯直通苏萨的御道约 2500 公里、设约 90 处驿站，信使接力传递。希罗多德赞叹「无论雨雪黑夜都不能阻止他们跑完全程」。", "source": "希罗多德 v.52—53"}, {"year": -513, "headline": "大流士远征斯基泰与色雷斯", "site": "达达尼尔", "coord": [26.4, 40.2], "detail": "大流士渡博斯普鲁斯与多瑙河远征斯基泰，虽未成功，却确立了对赫勒斯滂与色雷斯的控制，为希波战争完成战略布局。", "source": "希罗多德 iv"}, {"year": -499, "headline": "爱奥尼亚起义：米利都求援雅典", "site": "米利都", "coord": [27.28, 37.53], "detail": "米利都僭主阿里斯塔哥拉斯鼓动爱奥尼亚希腊城邦反抗波斯，并赴希腊本土求援。雅典派 20 艘船、埃雷特里亚派 5 艘，义军一度焚毁萨第斯。这次「烧城」成为波斯大王薛西斯远征希腊的口实。", "source": "希罗多德 v.28—v.103"}, {"year": -494, "headline": "拉德海战，米利都被毁", "site": "米利都", "coord": [27.28, 37.53], "detail": "波斯舰队在米利都以西的拉德岛海战击溃爱奥尼亚联合舰队，随后屠米利都、迁其民。雅典上演普律尼科斯悲剧《米利都的陷落》时观众痛哭，被罚千德拉克马——这是希波战争情绪的直接证据。", "source": "希罗多德 vi.18—21"}, {"year": -492, "headline": "第一次波斯远征希腊", "site": "达达尼尔", "coord": [26.4, 40.2], "detail": "马多尼乌斯渡赫勒斯滂，舰队在阿陀斯海角遇风暴覆没；两年后达提斯与阿尔塔弗涅斯再度出征，在马拉松被雅典击败。", "source": "希罗多德 vi"}, {"year": -480, "headline": "薛西斯一世渡赫勒斯滂远征希腊", "site": "达达尼尔", "coord": [26.4, 40.2], "detail": "薛西斯一世以浮桥渡赫勒斯滂，号称百万大军远征希腊。温泉关、萨拉米斯海战后波斯海军受挫，次年普拉蒂亚陆战再败。安纳托利亚的希腊城邦短暂获得自主。", "source": "希罗多德 vii—ix"}, {"year": -450, "headline": "萨尔迪斯的铸币与行省税", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "波斯在萨尔迪斯铸造金币（daric）与银币（siglos），安纳托利亚既是帝国税基也是货币经济最发达的地区之一。", "source": "钱币学研究"}, {"year": -400, "headline": "小居鲁士在萨第斯起兵", "site": "萨第斯", "coord": [28.04, 38.48], "detail": "波斯王子小居鲁士在萨第斯集结希腊雇佣军反叛兄长阿尔塔薛西斯二世，库纳克萨战死后希腊人北撤，即色诺芬《长征记》记载的撤退。", "source": "《长征记》i"}, {"year": -386, "headline": "《大王和约》：西部希腊城邦复归波斯", "site": "苏萨", "coord": [48.26, 32.19], "detail": "斯巴达与波斯签订《安塔尔基达斯和约》（大王和约）：小亚细亚希腊城邦重归波斯，换取波斯的金钱支持。这是希腊城邦体系首次以「大王」意志划界，也埋下了马其顿东进的伏笔。", "source": "色诺芬《希腊史》v.1.31"}, {"year": -334, "headline": "波斯治下的城市与混合精英", "site": "以弗所", "coord": [27.34, 37.94], "detail": "波斯时期安纳托利亚城市由「僭主—总督—神庙」三重结构治理，地方贵族与波斯王室通婚，形成融合希腊、吕底亚与波斯元素的精英阶层。", "source": "Briant《从居鲁士到亚历山大》"}], "settlements": [{"ancient": "萨尔迪斯行省治所", "modern": "萨尔特", "coord": [28.04, 38.48], "isCapital": true, "remark": "波斯小亚细亚行政中心", "source": "Briant《从居鲁士到亚历山大》"}, {"ancient": "达斯基雷翁", "modern": "埃尔吉耶斯一带", "coord": [30.16, 39.3], "isCapital": false, "remark": "弗里吉亚行省治所", "source": "Briant《从居鲁士到亚历山大》"}, {"ancient": "波斯波利斯", "modern": "设拉子附近", "coord": [52.89, 29.94], "isCapital": false, "remark": "帝国礼仪都城", "source": "Briant《从居鲁士到亚历山大》"}, {"ancient": "苏萨", "modern": "舒什", "coord": [48.26, 32.19], "isCapital": false, "remark": "帝国行政都城", "source": "Susa 发掘报告（de Morgan、Ghirshman）/ 汉谟拉比法典出土记录"}, {"ancient": "哈利卡纳苏斯", "modern": "博德鲁姆", "coord": [27.42, 37.04], "isCapital": false, "remark": "摩索拉斯陵墓", "source": "Briant《从居鲁士到亚历山大》"}, {"ancient": "帕加马", "modern": "贝尔加马", "coord": [27.18, 39.12], "isCapital": false, "source": "Altertümer von Pergamon 系列 / Hansen《阿塔罗斯王朝的帕加马》"}, {"ancient": "特拉佩祖斯", "modern": "特拉布宗", "coord": [39.72, 41.0], "isCapital": false, "remark": "黑海希腊殖民城", "source": "Briant《从居鲁士到亚历山大》"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.23, 31.78], "remark": "波斯敕令归回重建圣殿", "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}, {"ancient": "孟菲斯", "modern": "孟菲斯遗址（埃及）", "coord": [31.25, 29.85], "remark": "波斯埃及行省首府", "source": "Memphis 发掘报告（埃及文物最高委员会）"}, {"ancient": "西顿", "modern": "赛达（黎巴嫩）", "coord": [35.37, 33.56], "remark": "腓尼基城邦，波斯海军主要提供者", "source": "《剑桥古代史》卷 4 / Eshmunazar 石棺铭文"}]},
  {"key": "alexander", "title": "亚历山大与继业者", "badge": "继业者", "fromYear": -334, "toYear": -281, "focusYear": -323, "tint": "#8f6f3f", "seat": "吕西马基亚 · 安条克", "summary": "前 334 年亚历山大渡赫勒斯滂，前 333 年伊苏斯之战、前 331 年高加米拉之战灭波斯，前 323 年卒于巴比伦。此后“继业者”（Diadochi）争夺：安提柯、利西马科斯、塞琉古、托勒密，前 301 年伊普苏斯之战后安纳托利亚三分；前 281 年库鲁佩迪安之战利西马科斯阵亡，塞琉古短暂统一小亚细亚。同期比提尼亚、卡帕多细亚、本都本土王朝自立。", "sourceFiles": ["diadochi"], "phases": [{"until": -334, "snap": "s_alexander", "overview": "前 334 年 · 亚历山大东征：格拉尼库斯之战后小亚细亚诸城次第归附，波斯统治动摇。"}, {"until": -325, "snap": "s_alexander_east", "overview": "前 325 年 · 亚历山大末期：东征结束后继业者整军，安纳托利亚由各将分领。"}, {"until": -323, "snap": "s_alexander_death", "overview": "前 323 年 · 亚历山大卒：巴比伦分封，安纳托利亚成为继业者争夺的主战场。"}, {"until": -301, "snap": "s_ipsus", "overview": "前 301 年 · 伊普苏斯之战：安提柯阵亡，安纳托利亚三分：利西马科斯、塞琉古、本土王朝并立。"}, {"until": -281, "snap": "s_curupedium", "overview": "前 281 年 · 库鲁佩迪安之战：利西马科斯战死，塞琉古短暂统一小亚细亚；帕加马、本都、比提尼亚自立。"}], "milestones": [{"year": -334, "headline": "亚历山大渡赫勒斯滂，格拉尼库斯之战", "site": "格拉尼库斯河", "coord": [27.25, 40.13], "detail": "亚历山大率马其顿军渡赫勒斯滂，在格拉尼库斯河与波斯诸总督的联军首战。他亲自率骑兵冲锋，几乎被砍死；此役后小亚细亚西部门户洞开，诸城次第归附。", "source": "阿里安《远征记》i.13—16 / 普鲁塔克"}, {"year": -333, "headline": "伊苏斯之战：亚历山大击溃大流士三世", "site": "伊苏斯", "coord": [36.2, 36.85], "detail": "伊苏斯之战，亚历山大以右翼骑兵突入波斯中军，大流士三世弃车而逃，其母、妻、女被俘。亚历山大以礼待之，宣称自己是「大流士的继承者」而非毁灭者。", "source": "阿里安 ii.6—13"}, {"year": -331, "headline": "高加米拉之战，波斯帝国灭亡", "site": "高加米拉", "coord": [43.55, 36.55], "detail": "高加米拉（今伊拉克北部）决战，亚历山大以斜线阵诱使波斯战线出现缺口，直插大流士中军。大流士再度逃离，随后被部将杀死，阿契美尼德帝国灭亡，亚历山大成为「亚洲之王」。", "source": "阿里安 iii.8—15"}, {"year": -330, "headline": "焚毁波斯波利斯", "site": "波斯波利斯", "coord": [52.89, 29.94], "detail": "亚历山大火焚波斯波利斯王宫，象征阿契美尼德王朝终结；他随后采用波斯宫廷礼仪与「君主崇拜」，引发马其顿旧部不满。", "source": "阿里安 iii.18"}, {"year": -323, "headline": "亚历山大卒于巴比伦，继业者战争爆发", "site": "巴比伦", "coord": [44.42, 32.54], "detail": "亚历山大在巴比伦病逝（或中毒），年仅 32，未指定继承人。部将随即「巴比伦分封」，安纳托利亚被划给多个将领，由此开始四十年继业者战争。", "source": "阿里安 vii.24—28 / 狄奥多罗斯"}, {"year": -315, "headline": "安提柯一世控制小亚细亚", "site": "安条克", "coord": [36.16, 36.2], "detail": "继业者战争中安提柯一世占据小亚细亚大部，自称「亚洲统帅」，引发塞琉古、利西马科斯、卡山德结盟对抗，最终在伊普苏斯决战。", "source": "狄奥多罗斯 xix"}, {"year": -312, "headline": "塞琉古夺回巴比伦", "site": "安条克", "coord": [36.16, 36.2], "detail": "塞琉古夺回巴比伦并建立塞琉古纪元（312 年），随后西进小亚细亚，奠定塞琉古王朝对叙利亚与东部的统治。", "source": "阿庇安《叙利亚史》"}, {"year": -305, "headline": "塞琉古一世营建安条克", "site": "安条克", "coord": [36.16, 36.2], "detail": "塞琉古在奥龙特斯河畔建安条克，成为希腊化东方最大城市之一，与埃及的亚历山大里亚并称；其港口塞琉西亚是地中海—内陆贸易枢纽。", "source": "斯特拉波 xvi"}, {"year": -301, "headline": "伊普苏斯之战：安纳托利亚三分", "site": "伊普苏斯", "coord": [31.15, 38.85], "detail": "伊普苏斯之战，安提柯一世与其子德米特里对阵塞琉古、利西马科斯与卡山德联军。安提柯战死，其领地被瓜分；安纳托利亚由此分为利西马科斯（西部）、塞琉古（东部）与本土王朝三块。", "source": "普鲁塔克《德米特里传》/ 狄奥多罗斯 xx"}, {"year": -285, "headline": "利西马基亚的建立", "site": "吕西马基亚", "coord": [26.7, 40.55], "detail": "利西马科斯在色雷斯与赫勒斯滂之间建新都吕西马基亚，成为连接欧洲与安纳托利亚的军事枢纽与贸易口岸。", "source": "斯特拉波 / 考古"}, {"year": -283, "headline": "安纳托利亚诸小王国自立", "site": "尼科米底亚", "coord": [29.92, 40.77], "detail": "塞琉古与利西马科斯相继身死后，帕加马、本都、比提尼亚、卡帕多细亚等本土王朝纷纷自立，形成「小王国林立」的格局，为罗马的介入留出空间。", "source": "斯特拉波 xii"}], "settlements": [{"ancient": "亚历山大里亚·特洛阿斯", "modern": "达尔扬", "coord": [26.16, 39.55], "isCapital": false, "source": "狄奥多罗斯《历史丛书》卷 18—20"}, {"ancient": "安条克", "modern": "安塔基亚", "coord": [36.16, 36.2], "isCapital": false, "remark": "塞琉古西部都城（前 300 建）", "source": "Libanius 与《安条克志》/ Downey《安条克史》"}, {"ancient": "塞琉西亚", "modern": "巴格达附近", "coord": [44.52, 33.1], "isCapital": false, "remark": "底格里斯河畔塞琉古都城", "source": "狄奥多罗斯《历史丛书》卷 18—20"}, {"ancient": "吕西马基亚", "modern": "盖利博卢半岛", "coord": [26.7, 40.55], "isCapital": true, "remark": "利西马科斯都城", "source": "狄奥多罗斯《历史丛书》卷 18—20"}, {"ancient": "帕加马", "modern": "贝尔加马", "coord": [27.18, 39.12], "isCapital": false, "source": "Altertümer von Pergamon 系列 / Hansen《阿塔罗斯王朝的帕加马》"}, {"ancient": "尼西亚", "modern": "伊兹尼克", "coord": [29.72, 40.43], "isCapital": false, "source": "Akropolites《编年史》/ TIB"}, {"ancient": "阿马西亚", "modern": "阿马西亚", "coord": [35.83, 40.65], "isCapital": false, "remark": "本都王国旧都", "source": "狄奥多罗斯《历史丛书》卷 18—20"}, {"ancient": "亚历山大港", "modern": "亚历山大（埃及）", "coord": [29.92, 31.2], "remark": "托勒密王朝首都，地中海学术中心", "source": "Fraser《托勒密时期的亚历山大》"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.23, 31.78], "remark": "塞琉古与托勒密反复争夺的圣城", "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}]},
  {"key": "hellenistic", "title": "希腊化诸王国", "badge": "希腊化", "fromYear": -281, "toYear": -133, "focusYear": -188, "tint": "#b8892f", "seat": "帕加马 · 锡诺普 · 尼科米底亚", "summary": "安纳托利亚进入多王国并立：帕加马阿塔罗斯王朝与罗马结盟，前 188 年《阿帕米亚和约》后取得塞琉古在小亚细亚的大部；本都米特里达梯王朝在黑海南岸崛起，本都战争与罗马三度交锋（前 88—前 63）；比提尼亚、卡帕多细亚、加拉太、科马基尼为罗马的缓冲附庸。前 133 年阿塔罗斯三世遗赠帕加马给罗马，亚细亚行省成立。", "sourceFiles": ["hellenistic"], "phases": [{"until": -278, "snap": "s_galatian_invasion", "overview": "前 278 年 · 加拉太人入侵：凯尔特部族定居安纳托利亚中部，成为各王国的雇佣兵与边患。"}, {"until": -250, "snap": "s_galatia_settled", "overview": "前 250 年 · 加拉太定局：凯尔特诸部定居中部高原，成为各王国争相雇佣的兵源。"}, {"until": -240, "snap": "s_attalid_power", "overview": "前 240 年 · 阿塔罗斯王朝：阿塔罗斯一世击败加拉太人，帕加马成为西部最强王国。"}, {"until": -190, "snap": "s_magnesia", "overview": "前 190 年 · 马格尼西亚之战：罗马击败塞琉古安条克三世，势力首次深入小亚细亚。"}, {"until": -188, "snap": "s_apamea", "overview": "前 188 年 · 阿帕米亚和约：塞琉古退出托罗斯山以北，帕加马取得小亚细亚大部。"}, {"until": -133, "snap": "s_asia_province", "overview": "前 133 年 · 亚细亚行省：阿塔罗斯三世遗赠帕加马，罗马在亚洲的第一个行省设立。"}, {"until": -88, "snap": "s_mithridatic", "overview": "前 88 年 · 米特里达梯战争：本都国王发动“亚洲晚祷”，罗马在东方的统治遭重创。"}], "milestones": [{"year": -281, "headline": "库鲁佩迪安之战，利西马科斯阵亡", "site": "库鲁佩迪安", "coord": [27.05, 38.55], "detail": "库鲁佩迪安之战，塞琉古一世击败并杀死利西马科斯，短暂统一小亚细亚；他随即被托勒密·克劳努斯刺杀。塞琉古王朝由此稳固叙利亚与小亚细亚，帕加马、本都、比提尼亚趁机自立。", "source": "阿庇安《叙利亚史》"}, {"year": -261, "headline": "帕加马独立，阿塔罗斯王朝建立", "site": "帕加马", "coord": [27.18, 39.12], "detail": "帕加马的腓莱泰罗斯原为利西马科斯的守库人，前 281 年后自立；其侄欧迈尼斯一世在库鲁佩迪安战后正式建立阿塔罗斯王朝，定都帕加马。帕加马凭银矿、羊皮纸与阿塔罗斯柱廊成为东部文化中心。", "source": "Strabo xiii / 帕加马铭文"}, {"year": -230, "headline": "阿塔罗斯一世击败加拉太人，取“救主”称号", "site": "帕加马", "coord": [27.18, 39.12], "detail": "加拉太人（凯尔特三支：特罗克米、托里斯托波基、托利斯托波吉）入侵安纳托利亚中部。阿塔罗斯一世在卡伊科斯河源两度击败他们，取得「救主」（Soter）称号并立碑纪念；加拉太人此后定居高原，成为各王国的雇佣兵来源。", "source": "李维《罗马史》xxxviii / 帕加马纪念碑"}, {"year": -222, "headline": "帕加马图书馆与羊皮纸", "site": "帕加马", "coord": [27.18, 39.12], "detail": "帕加马图书馆藏书约二十万卷；因托勒密王朝禁止纸草出口，当地发展出精制羊皮纸（pergamena），与亚历山大里亚图书馆争雄。", "source": "老普林尼《博物志》xiii"}, {"year": -197, "headline": "罗马成为东方事务的裁决者", "site": "以弗所", "coord": [27.34, 37.94], "detail": "库诺斯克法莱之战后，罗马成为希腊—安纳托利亚事务的仲裁者，帕加马与本都皆以「罗马之友」自居并借此扩张。", "source": "波利比乌斯 / 李维"}, {"year": -190, "headline": "马格尼西亚之战", "site": "马格尼西亚", "coord": [27.5, 38.6], "detail": "罗马与帕加马联军击败塞琉古安条克三世，确立罗马在小亚细亚的仲裁权；次年《阿帕米亚和约》使塞琉古退出托罗斯山以北。", "source": "李维 xxxvii"}, {"year": -188, "headline": "《阿帕米亚和约》：塞琉古退出托罗斯山以北", "site": "阿帕米亚", "coord": [30.16, 38.07], "detail": "《阿帕米亚和约》结束罗马-塞琉古战争：安条克三世割让托罗斯山以北全部领地并赔款。帕加马与本都分得除奇里乞亚外的西部；罗马首次以「仲裁者」身份决定小亚细亚版图。", "source": "波利比乌斯 xxi / 李维 xxxviii"}, {"year": -150, "headline": "加拉太人与雇佣兵经济", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "加拉太诸部以武力出租为业，帕加马、比提尼亚、本都争相雇佣；其地后成为罗马的「加拉太行省」，安卡拉即其行政中心。", "source": "斯特拉波 xii"}, {"year": -133, "headline": "阿塔罗斯三世遗赠帕加马予罗马，亚细亚行省设立", "site": "帕加马", "coord": [27.18, 39.12], "detail": "帕加马末代国王阿塔罗斯三世在遗嘱中把王国赠予罗马，罗马以其地设「亚细亚行省」（Asia），是全罗马最富的省份之一。此后罗马以行省+附庸王国的双层结构管理安纳托利亚。", "source": "斯特拉波 xiv / 罗马史学家"}, {"year": -85, "headline": "《达达诺斯和约》", "site": "达达诺斯", "coord": [26.2, 40.1], "detail": "苏拉与米特里达梯六世缔结和约：本都赔款并退出西部，安纳托利亚城市在战火后普遍负债，罗马包税制度的弊端由此暴露。", "source": "阿庇安《米特里达梯战争》"}, {"year": -70, "headline": "米特里达梯战争的终结", "site": "锡诺普", "coord": [35.15, 42.03], "detail": "米特里达梯六世三度与罗马交战，最终在庞培追击下自尽；本都与比提尼亚并入罗马行省，黑海南岸的政治格局彻底改变。", "source": "阿庇安《米特里达梯战争》"}], "settlements": [{"ancient": "帕加马", "modern": "贝尔加马", "coord": [27.18, 39.12], "isCapital": true, "remark": "阿塔罗斯王朝都城，大祭坛与图书馆", "source": "Altertümer von Pergamon 系列 / Hansen《阿塔罗斯王朝的帕加马》"}, {"ancient": "锡诺普", "modern": "锡诺普", "coord": [35.15, 42.03], "isCapital": true, "remark": "本都王国都城", "source": "《剑桥古代史》卷 7—8"}, {"ancient": "尼科米底亚", "modern": "伊兹米特", "coord": [29.92, 40.77], "isCapital": true, "remark": "比提尼亚王国都城", "source": "《剑桥古代史》卷 8 / TIB（Bithynia）"}, {"ancient": "马扎卡", "modern": "开塞利", "coord": [35.49, 38.73], "isCapital": true, "remark": "卡帕多细亚王国都城", "source": "《剑桥古代史》卷 7—8"}, {"ancient": "安卡拉（安基拉）", "modern": "安卡拉", "coord": [32.86, 39.93], "isCapital": false, "remark": "加拉太部族中心", "source": "《剑桥古代史》卷 7—8"}, {"ancient": "阿芙洛狄西亚斯", "modern": "格伊拉", "coord": [28.72, 37.71], "isCapital": false, "source": "《剑桥古代史》卷 7—8"}, {"ancient": "米特里达提翁", "modern": "克尔克基莱西", "coord": [33.68, 39.85], "isCapital": false, "source": "《剑桥古代史》卷 7—8"}, {"ancient": "萨莫萨塔", "modern": "阿德亚曼", "coord": [38.28, 37.76], "isCapital": false, "remark": "科马基尼王国都城", "source": "《剑桥古代史》卷 7—8"}]},
  {"key": "roman", "title": "罗马安纳托利亚", "badge": "罗马", "fromYear": -133, "toYear": 330, "focusYear": 117, "tint": "#8f3f3f", "seat": "以弗所 · 尼科米底亚 · 安条克", "summary": "奥古斯都后小亚细亚进入长期和平：亚细亚、比提尼亚-本都、加拉太、卡帕多细亚、奇里乞亚、吕基亚-潘菲利亚等行省并为帝国东部富庶地带，以弗所、帕加马、萨第斯、安条克为大城市。图拉真 114—117 年短暂设立亚美尼亚与美索不达米亚行省；哈德良时退回。235 年危机后波斯萨珊崛起，260 年沙普尔一世俘获瓦勒良。", "sourceFiles": ["roman_conquest", "roman_empire"], "phases": [{"until": -100, "snap": "s_provincial_asia", "overview": "前 100 年 · 行省制成形：亚细亚行省与比提尼亚、卡帕多细亚等附庸王国并存的结构稳固。"}, {"until": -63, "snap": "s_pompey_east", "overview": "前 63 年 · 庞培重组东方：本都王国灭亡、塞琉古被废，比提尼亚-本都与奇里乞亚行省设立。"}, {"until": -31, "snap": "s_actium", "overview": "前 31 年 · 亚克兴之后：屋大维战胜安东尼，东方行省重新划分，元首制时代开始。"}, {"until": -27, "snap": "s_augustus", "overview": "前 27 年 · 奥古斯都时代：元首制确立，东方行省进入长期和平；以弗所、帕加马繁盛。"}, {"until": 70, "snap": "s_flavian", "overview": "70 年 · 弗拉维王朝：行省城市化推进，道路网与皇帝崇拜庙宇遍布西部城市。"}, {"until": 117, "snap": "s_trajan_peak", "overview": "117 年 · 图拉真极盛：短暂设立亚美尼亚与美索不达米亚行省，帝国东部达波斯湾。"}, {"until": 200, "snap": "s_severan", "overview": "200 年 · 塞维鲁时代：帕提亚转萨珊，东方边境压力上升，军团驻防加重。"}, {"until": 260, "snap": "s_crisis_3c", "overview": "260 年 · 三世纪危机：埃德萨之战瓦勒良被俘，萨珊崛起压迫东方边境。"}, {"until": 300, "snap": "s_tetrarchy", "overview": "300 年 · 四帝共治：戴克里先行省改革细分行省，安纳托利亚被划入多个新行省与教区。"}, {"until": 330, "snap": "s_constantinople", "overview": "330 年 · 君士坦丁堡建都：拜占庭改名君士坦丁堡，帝国重心东移。"}], "milestones": [{"year": -129, "headline": "亚细亚行省的包税制", "site": "以弗所", "coord": [27.34, 37.94], "detail": "罗马以包税公司（publicani）征收亚细亚行省税，引发地方商人与元老院的长期冲突；西塞罗曾为被控勒索的总督弗拉库斯辩护。", "source": "西塞罗《为弗拉库斯辩护》"}, {"year": -88, "headline": "「亚洲晚祷」大屠杀", "site": "以弗所", "coord": [27.34, 37.94], "detail": "米特里达梯六世策划一夜之间屠杀安纳托利亚的罗马与意大利商人（古代文献称约八万人），是古代规模最大的商业侨民屠杀之一。", "source": "阿庇安 / 普鲁塔克《苏拉传》"}, {"year": 17, "headline": "提比略的地震赈灾", "site": "以弗所", "coord": [27.34, 37.94], "detail": "公元 17 年大地震毁坏以弗所等十二座城市，提比略免除赋税并拨巨款重建；罗马皇帝由此被纳入东方城市的宗教性颂扬体系。", "source": "塔西佗《编年史》ii.47"}, {"year": 64, "headline": "保罗在以弗所传道与银匠骚乱", "site": "以弗所", "coord": [27.34, 37.94], "detail": "使徒保罗在亚细亚行省传道两年，以弗所的阿耳忒弥斯神庙与银匠行会因神像生意受损而暴动；基督教自此在小亚细亚扎根。", "source": "《使徒行传》19"}, {"year": 114, "headline": "图拉真设亚美尼亚、美索不达米亚行省", "site": "泰西封", "coord": [44.58, 33.09], "detail": "图拉真东征帕提亚，攻陷泰西封，短暂设立亚美尼亚与美索不达米亚两行省，帝国东部抵达波斯湾。这是罗马版图的最大范围，但图拉真死后即被放弃。", "source": "狄奥·卡西乌斯 lxviii"}, {"year": 117, "headline": "哈德良放弃东方新省，退回幼发拉底河", "site": "安条克", "coord": [36.16, 36.2], "detail": "哈德良继位后放弃图拉真的东方新省，退回幼发拉底河一线，以「守成为主」。他巡视东方、重建安条克与以弗所的公共建筑，东方行省进入长期和平与城市化高峰。", "source": "《奥古斯都史》哈德良传"}, {"year": 120, "headline": "罗马道路网与邮驿", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "以弗所—安卡拉—安条克的道路网承担军团调动与邮驿，安卡拉成为加拉太行省枢纽，并留下奥古斯都神庙的《功德录》双语碑铭。", "source": "罗马道路研究 / 安卡拉纪念碑"}, {"year": 249, "headline": "德西乌斯迫害与殉道记忆", "site": "以弗所", "coord": [27.34, 37.94], "detail": "德西乌斯下令全帝国献祭，安纳托利亚基督徒大量殉道；「叛教者」能否重新入会引发长期争论，塑造了教会的忏悔制度。", "source": "优西比乌《教会史》"}, {"year": 251, "headline": "哥特人袭掠黑海南岸", "site": "特拉比松", "coord": [39.72, 41.0], "detail": "哥特人自黑海北岸渡海袭掠本都与卡帕多细亚，焚毁神庙与城市，暴露三世纪危机中的海防漏洞；特拉比松此后加筑城墙。", "source": "佐西莫斯 i.32"}, {"year": 260, "headline": "埃德萨之战：萨珊沙普尔一世俘获瓦勒良", "site": "埃德萨", "coord": [38.79, 37.15], "detail": "萨珊皇帝沙普尔一世在埃德萨之战中俘获罗马皇帝瓦勒良（Valerian），这是罗马史上罕见的一次皇帝被俘。萨珊铭文（纳克什-鲁斯塔姆）把此事列为三大功业之一，罗马东方防线长期动摇。", "source": "《奥古斯都史》/ 沙普尔铭文"}, {"year": 325, "headline": "尼西亚公会议：基督教大公会议首次召开", "site": "尼西亚", "coord": [29.72, 40.43], "detail": "君士坦丁召集第一次尼西亚公会议，确立《尼西亚信经》并谴责阿里乌派。安纳托利亚教会由此形成以君士坦丁堡、以弗所、尼西亚为中心的格局，此后数百年教义争论都围绕这片土地展开。", "source": "优西比乌《君士坦丁传》/ 会议文献"}, {"year": 330, "headline": "君士坦丁迁都君士坦丁堡", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "君士坦丁把首都从罗马迁到博斯普鲁斯海峡西岸的拜占庭，改名君士坦丁堡。帝国重心东移，安纳托利亚从「东部行省」变成帝国的腹地，城市、道路与军防体系随之重塑。", "source": "佐西莫斯《新史》/ 编年史"}, {"year": 381, "headline": "君士坦丁堡公会议", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "第二次大公会议确立尼西亚—君士坦丁堡信经，并把君士坦丁堡教座提到罗马之后；安纳托利亚的教会格局（君士坦丁堡、以弗所、尼西亚）由此定型。", "source": "会议文献 / 教会史"}], "settlements": [{"ancient": "以弗所", "modern": "塞尔丘克", "coord": [27.34, 37.94], "isCapital": false, "remark": "亚细亚都会，塞尔苏斯图书馆", "source": "ÖAI 以弗所发掘报告 /《以弗所铭文集成》(IvE)"}, {"ancient": "帕加马", "modern": "贝尔加马", "coord": [27.18, 39.12], "isCapital": false, "remark": "阿斯克勒庇俄斯圣所", "source": "Altertümer von Pergamon 系列 / Hansen《阿塔罗斯王朝的帕加马》"}, {"ancient": "拜占庭", "modern": "伊斯坦布尔", "coord": [28.98, 41.01], "isCapital": false, "remark": "330 年成为新都", "source": "《巴林顿希腊罗马世界地图集》/ Magie《罗马统治下的小亚细亚》"}, {"ancient": "尼西亚", "modern": "伊兹尼克", "coord": [29.72, 40.43], "isCapital": false, "source": "Akropolites《编年史》/ TIB"}, {"ancient": "凯撒利亚（马扎卡）", "modern": "开塞利", "coord": [35.49, 38.73], "isCapital": false, "source": "《巴林顿希腊罗马世界地图集》/ Magie《罗马统治下的小亚细亚》"}, {"ancient": "安基拉", "modern": "安卡拉", "coord": [32.86, 39.93], "isCapital": false, "remark": "奥古斯都神庙铭文", "source": "《巴林顿希腊罗马世界地图集》/ Magie《罗马统治下的小亚细亚》"}, {"ancient": "梅利泰内", "modern": "马拉蒂亚", "coord": [38.31, 38.35], "isCapital": false, "remark": "东部军区重镇", "source": "《巴林顿希腊罗马世界地图集》/ Magie《罗马统治下的小亚细亚》"}, {"ancient": "亚历山大港", "modern": "亚历山大（埃及）", "coord": [29.92, 31.2], "remark": "罗马埃及行省首府，帝国第二大城市", "source": "Fraser《托勒密时期的亚历山大》"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.23, 31.78], "remark": "70 年第二圣殿被毁", "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}, {"ancient": "帕尔米拉", "modern": "泰德穆尔（叙利亚）", "coord": [38.27, 34.55], "remark": "沙漠商队之城，270 年自立为帝国", "source": "Palmyra 铭文集成（PAT）/《剑桥古代史》卷 12"}, {"ancient": "安条克", "modern": "安塔基亚（土耳其）", "coord": [36.16, 36.2], "remark": "罗马叙利亚行省首府，东方军团大本营", "source": "Libanius 与《安条克志》/ Downey《安条克史》"}]},
  {"key": "byzantine", "title": "拜占庭安纳托利亚", "badge": "拜占庭", "fromYear": 330, "toYear": 1071, "focusYear": 970, "tint": "#8f3f6f", "seat": "君士坦丁堡", "summary": "330 年君士坦丁堡建都。602—628 年东罗马-萨珊大战耗尽双方，636 年雅尔穆克战役后阿拉伯人夺取叙利亚，安纳托利亚成为拜占庭与哈里发的“边境地带”（thughūr）。7—9 世纪推行军区（theme）制：安纳托利亚、阿尔梅尼亚克、色雷斯西亚、奥普西金、布凯拉里、卡帕多细亚等军区。9—10 世纪马其顿王朝反攻，963—969 年收复奇里乞亚与安条克。1071 年曼齐刻尔特战败后失中部门户。", "sourceFiles": ["byzantine"], "phases": [{"until": 450, "snap": "s_theodosian", "overview": "450 年 · 狄奥多西之后：451 年卡尔西顿公会议确立安纳托利亚教会格局，城市文明稳定。"}, {"until": 550, "snap": "s_justinian", "overview": "550 年 · 查士丁尼时代：收复西部与北非，编《民法大全》；安纳托利亚行省城市繁荣。"}, {"until": 600, "snap": "s_heracleius", "overview": "600 年 · 希拉克略时代：东罗马与萨珊长达三十年的大战，安纳托利亚被反复劫掠。"}, {"until": 640, "snap": "s_arab_conquest", "overview": "640 年 · 阿拉伯征服：雅尔穆克战役后叙利亚失守，安纳托利亚成为拜占庭与哈里发的边境地带。"}, {"until": 700, "snap": "s_arab_raids", "overview": "700 年 · 阿拉伯袭掠：君士坦丁堡两次被围后，边境沿托罗斯山形成无人区与要塞线。"}, {"until": 800, "snap": "s_theme_system", "overview": "800 年 · 军区制时代：安纳托利亚、阿尔梅尼亚克等军区成形，与阿拉伯人长期拉锯。"}, {"until": 900, "snap": "s_byz_recovery", "overview": "900 年 · 拜占庭反攻：收复爱琴海岛屿与东部军区失地，向奇里乞亚推进。"}, {"until": 970, "snap": "s_macedonian", "overview": "970 年 · 马其顿王朝中兴：尼基弗鲁斯二世收复奇里乞亚与安条克，帝国转入反攻。"}, {"until": 1025, "snap": "s_basil_death", "overview": "1025 年 · 巴西尔二世身后：帝国疆域极盛而军力内耗，中央集权松弛，边防将领自立。"}], "milestones": [{"year": 330, "headline": "君士坦丁堡建都，东罗马时代开始", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "君士坦丁堡建都后，安纳托利亚成为帝国的主要兵源与粮仓。君士坦丁堡的人口、元老院与教会使之成为「新罗马」，西部则逐渐在蛮族迁徙中脱离。", "source": "Ostrogorsky《拜占庭国家史》"}, {"year": 532, "headline": "尼卡暴动与圣索菲亚重建", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "君士坦丁堡的尼卡暴动几乎推翻查士丁尼，事后他重建圣索菲亚大教堂，成为拜占庭宗教建筑与帝国意识形态的巅峰。", "source": "普罗可比《战史》"}, {"year": 541, "headline": "查士丁尼瘟疫", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "鼠疫自埃及经海路传入，君士坦丁堡死亡过半；安纳托利亚人口与税基长期萎缩，帝国由扩张转为守成。", "source": "普罗可比《战史》ii"}, {"year": 614, "headline": "萨珊劫掠安纳托利亚城市", "site": "凯撒利亚", "coord": [35.49, 38.73], "detail": "萨珊军队劫掠安纳托利亚城市并夺取「真十字架」，拜占庭在 7 世纪初一度濒临崩溃，直到 628 年反攻得手。", "source": "《复活节编年史》"}, {"year": 626, "headline": "阿瓦尔人与波斯人围攻君士坦丁堡", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "阿瓦尔人与萨珊联军自陆海两面围城，拜占庭靠海军与城内补给守住城市；此役与随后的雅尔穆克形成帝国命运的分水岭。", "source": "《复活节编年史》"}, {"year": 636, "headline": "雅尔穆克战役后阿拉伯人夺取叙利亚", "site": "雅尔穆克", "coord": [35.85, 32.8], "detail": "雅尔穆克战役，拜占庭东方军被阿拉伯穆斯林军击溃，希拉克略皇帝退出叙利亚。此后安纳托利亚成为拜占庭与哈里发之间的边境地带，托罗斯山沿线形成要塞化的「边境区」。", "source": "Theophanes《编年史》/ 早期伊斯兰史料"}, {"year": 717, "headline": "阿拉伯人围攻君士坦丁堡失败", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "阿拉伯哈里发苏莱曼的军队自陆海两面围攻君士坦丁堡一年余，因希腊火、饥荒与保加尔的袭扰而失败。此役使拜占庭得以存续，也终结了倭马亚王朝的北进。", "source": "Theophanes / 阿拉伯史料"}, {"year": 740, "headline": "阿克罗伊农之战", "site": "阿克罗伊农", "coord": [30.6, 38.85], "detail": "利奥三世与君士坦丁五世在阿克罗伊农击败倭马亚军队，终结阿拉伯对安纳托利亚腹地的大规模入侵，军区制由此稳固。", "source": "Theophanes《编年史》"}, {"year": 843, "headline": "圣像崇拜恢复", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "圣像破坏运动结束，「正统周日」确立；安纳托利亚的修道院（如卡帕多细亚岩窟修道院）与圣像艺术随之复兴。", "source": "Theophanes《编年史》"}, {"year": 860, "headline": "罗斯人袭掠博斯普鲁斯", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "罗斯舰队袭击博斯普鲁斯沿岸与王子群岛，拜占庭以外交与通商（与可萨、罗斯）应对，黑海贸易格局随之变化。", "source": "牧首佛提乌讲道"}, {"year": 963, "headline": "尼基弗鲁斯二世收复奇里乞亚与安条克", "site": "安条克", "coord": [36.16, 36.2], "detail": "尼基弗鲁斯二世（拜占庭将领，曾收复克里特与塞浦路斯）登基后大举东征，967—969 年收复奇里乞亚、塞浦路斯与安条克。安纳托利亚东部从边境变成帝国腹地，马其顿王朝进入中兴。", "source": "Leo the Deacon《历史》"}, {"year": 1037, "headline": "塞尔柱人西进与亚美尼亚高原", "site": "大不里士", "coord": [46.29, 38.07], "detail": "图格里勒贝格建立大塞尔柱帝国，控制伊朗与亚美尼亚高原，开始对高加索与安纳托利亚边境施压，为 1071 年的曼齐刻尔特埋下伏笔。", "source": "《剑桥伊朗史》"}, {"year": 1071, "headline": "曼齐刻尔特之战：拜占庭丢失安纳托利亚门户", "site": "曼齐刻尔特", "coord": [42.53, 39.15], "detail": "曼齐刻尔特之战，塞尔柱苏丹阿尔普·阿尔斯兰击败并俘虏拜占庭皇帝罗曼努斯四世。拜占庭随即爆发内战，突厥部落大规模进入安纳托利亚腹地，帝国从此失去对高原的控制。", "source": "Attaleiates《历史》/ Cahen"}, {"year": 1176, "headline": "密列奥塞法隆之后的拜占庭战略转向", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "战败后拜占庭放弃清除突厥人的努力，转为修筑边境要塞、依赖通婚与雇佣突厥部队维持秩序，安纳托利亚的突厥化由此不可逆。", "source": "Choniates《历史》"}], "settlements": [{"ancient": "君士坦丁堡", "modern": "伊斯坦布尔", "coord": [28.98, 41.01], "isCapital": true, "source": "Tabula Imperii Byzantini / Ostrogorsky《拜占庭国家史》"}, {"ancient": "阿莫里翁", "modern": "阿菲永附近", "coord": [30.6, 38.85], "isCapital": false, "remark": "安纳托利亚军区重镇", "source": "Tabula Imperii Byzantini / Ostrogorsky《拜占庭国家史》"}, {"ancient": "安基拉", "modern": "安卡拉", "coord": [32.86, 39.93], "isCapital": false, "source": "Tabula Imperii Byzantini / Ostrogorsky《拜占庭国家史》"}, {"ancient": "塞琉西亚", "modern": "锡利夫凯", "coord": [33.93, 36.38], "isCapital": false, "source": "Tabula Imperii Byzantini / Ostrogorsky《拜占庭国家史》"}, {"ancient": "阿尼", "modern": "阿尼（卡尔斯）", "coord": [43.57, 40.51], "isCapital": false, "remark": "亚美尼亚巴格拉图尼王朝都城", "source": "Tabula Imperii Byzantini / Ostrogorsky《拜占庭国家史》"}, {"ancient": "特拉比松", "modern": "特拉布宗", "coord": [39.72, 41.0], "isCapital": false, "source": "Ostrogorsky / Bryer《特拉比松帝国》"}, {"ancient": "阿塔利亚", "modern": "安塔利亚", "coord": [30.7, 36.89], "isCapital": false, "source": "Tabula Imperii Byzantini / Ostrogorsky《拜占庭国家史》"}, {"ancient": "亚历山大港", "modern": "亚历山大（埃及）", "coord": [29.92, 31.2], "remark": "641 年落入阿拉伯人之手，帝国粮仓尽失", "source": "Fraser《托勒密时期的亚历山大》"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.23, 31.78], "remark": "614 年萨珊劫掠，638 年阿拉伯接管", "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}, {"ancient": "大马士革", "modern": "大马士革（叙利亚）", "coord": [36.29, 33.51], "remark": "635 年陷落，661 年起为倭马亚王朝首都", "source": "《剑桥伊斯兰史》卷 1 / Ibn ʿAsākir《大马士革史》"}, {"ancient": "开罗", "modern": "福斯塔特—开罗（埃及）", "coord": [31.24, 30.04], "remark": "641 年福斯塔特建城，埃及行省新首府", "source": "《剑桥埃及史》/ Ibn Iyas《历代奇事》"}]},
  {"key": "seljuk", "title": "突厥入主与十字军", "badge": "罗姆苏丹国", "fromYear": 1071, "toYear": 1243, "focusYear": 1176, "tint": "#3f8f6a", "seat": "科尼亚 · 尼西亚 · 锡瓦斯", "summary": "1071 年曼齐刻尔特之战后突厥人涌入，1077 年苏莱曼·伊本·库塔尔米什立罗姆苏丹国（都科尼亚），丹麦门德王朝据中北部，阿尔图格、萨尔图克、门古哲克诸贝伊国在东部，曼努埃尔一世 1176 年密列奥塞法隆战败。1097 年第一次十字军的尼西亚、多里莱乌姆之战与 1204 年第四次十字军攻陷君士坦丁堡，以及 1204—1261 年尼西亚帝国，重塑小亚细亚政治。1243 年克塞山之战苏丹国臣属蒙古。", "sourceFiles": ["seljuk"], "phases": [{"until": 1071, "snap": "s_manzikert", "overview": "1071 年 · 曼齐刻尔特之战：罗曼努斯四世战败被俘，突厥人进入安纳托利亚腹地。"}, {"until": 1097, "snap": "s_first_crusade", "overview": "1097 年 · 第一次十字军：尼西亚、多里莱乌姆之战后拜占庭收复西部沿海，十字军东进。"}, {"until": 1120, "snap": "s_crusader_early", "overview": "1120 年 · 十字军国家初立：耶路撒冷王国、安条克公国与的黎波里伯国立足，叙利亚的塞尔柱王公内斗；赞吉王朝尚未兴起。"}, {"until": 1150, "snap": "s_danismend_end", "overview": "1150 年 · 丹麦门德衰亡：罗姆苏丹国兼并中北安纳托利亚，突厥人的地方政权趋于统一。"}, {"until": 1176, "snap": "s_myriokephalon", "overview": "1176 年 · 密列奥塞法隆之战：曼努埃尔一世败于基利杰阿尔斯兰二世，拜占庭反攻终结。"}, {"until": 1204, "snap": "s_fourth_crusade", "overview": "1204 年 · 第四次十字军：君士坦丁堡陷落，尼西亚帝国、特拉比松帝国与拉丁帝国并立。"}, {"until": 1230, "snap": "s_rum_peak", "overview": "1230 年 · 罗姆苏丹国鼎盛：阿拉丁·凯库巴德控制地中海与黑海港口，塞尔柱商队网络达顶峰。"}], "milestones": [{"year": 1071, "headline": "曼齐刻尔特之战，突厥人进入安纳托利亚", "site": "曼齐刻尔特", "coord": [42.53, 39.15], "detail": "曼齐刻尔特之后，塞尔柱宗王苏莱曼·伊本·库塔尔米什在安纳托利亚建罗姆苏丹国（「罗姆」即罗马之地），先后定都尼西亚、科尼亚。突厥化与伊斯兰化从此在高原加速。", "source": "Cahen《前奥斯曼土耳其》"}, {"year": 1077, "headline": "苏莱曼·伊本·库塔尔米什立罗姆苏丹国", "site": "尼西亚", "coord": [29.72, 40.43], "detail": "苏莱曼·伊本·库塔尔米什是塞尔柱宗室，曼齐刻尔特之后在安纳托利亚西部自立，先以尼西亚为都，前推至科尼亚。\n「罗姆」意即罗马之地，宣称继承拜占庭在东方的统治；1097 年尼西亚被十字军夺走后，苏丹国重心南移科尼亚。", "source": "Cahen《前奥斯曼土耳其》"}, {"year": 1081, "headline": "尼西亚成为罗姆苏丹国都城", "site": "尼西亚", "coord": [29.72, 40.43], "detail": "罗姆苏丹国以尼西亚为都，控制博斯普鲁斯对岸，直接威胁君士坦丁堡；直到 1097 年第一次十字军夺取尼西亚，苏丹国才南迁科尼亚。", "source": "Anna Komnene《阿莱克修斯传》"}, {"year": 1086, "headline": "突厥化与「两重社会」", "site": "科尼亚", "coord": [32.49, 37.87], "detail": "突厥游牧部落与希腊农民混居，形成草原税制与城市手工业并存的双重社会；地名大量突厥化，基督教社群逐步减少。", "source": "Cahen《前奥斯曼土耳其》"}, {"year": 1097, "headline": "第一次十字军收复尼西亚，多里莱乌姆之战", "site": "多里莱乌姆", "coord": [30.52, 39.62], "detail": "第一次十字军应拜占庭皇帝阿莱克修斯之请东征：攻下尼西亚交还拜占庭，多里莱乌姆之战击溃罗姆苏丹基利杰阿尔斯兰一世。十字军随后建立安条克公国与埃德萨伯国。", "source": "Anna Komnene《阿莱克修斯传》"}, {"year": 1116, "headline": "拜占庭—罗姆边界的长期稳定", "site": "科尼亚", "coord": [32.49, 37.87], "detail": "阿莱克修斯与约翰二世时期，双方以门德雷斯河与幼发拉底一线形成长期边界，游牧定居、贸易与朝贡并行，安纳托利亚出现突厥-希腊混合社会。", "source": "《剑桥土耳其史》"}, {"year": 1145, "headline": "塞尔柱商队驿站网络成形", "site": "锡瓦斯", "coord": [37.02, 39.75], "detail": "罗姆苏丹国修建数十座商队客栈（han），提供三日免费食宿与武装保护；安纳托利亚由此成为欧亚贸易的枢纽，锡瓦斯与开塞利最盛。", "source": "塞尔柱建筑铭文与瓦克夫文书"}, {"year": 1147, "headline": "第二次十字军穿越安纳托利亚", "site": "多里莱乌姆", "coord": [30.5, 39.5], "detail": "康拉德三世的德意志军队在多里莱乌姆被突厥骑兵击溃，撤退途中大量死亡；此役暴露十字军对突厥骑射战术与缺水的严重误判。", "source": "奥托《腓特烈一世纪》"}, {"year": 1158, "headline": "曼努埃尔的东方远征", "site": "阿达纳", "coord": [35.32, 37.0], "detail": "曼努埃尔一世迫使罗姆苏丹称臣、奇里乞亚亚美尼亚割地，短暂恢复拜占庭在东南的宗主权；但其后继者无力维持。", "source": "Choniates《历史》"}, {"year": 1176, "headline": "密列奥塞法隆之战：曼努埃尔一世败于基利杰阿尔斯兰二世", "site": "密列奥塞法隆", "coord": [31.35, 38.15], "detail": "拜占庭皇帝曼努埃尔一世亲征罗姆苏丹国，在密列奥塞法隆山口的隘路遭基利杰阿尔斯兰二世伏击而惨败。这是他最后一次试图清除突厥人的努力，拜占庭此后转守。", "source": "Kinnamos / Choniates"}, {"year": 1214, "headline": "尼西亚帝国与罗姆的边界协定", "site": "尼西亚", "coord": [29.72, 40.43], "detail": "第四次十字军后，尼西亚帝国成为拜占庭正统继承者，与罗姆苏丹国划定边界，安纳托利亚西部形成长期均势。", "source": "Akropolites《编年史》"}, {"year": 1219, "headline": "罗姆苏丹国夺取黑海与地中海港口", "site": "阿拉尼亚", "coord": [32.0, 36.54], "detail": "凯库巴德一世夺取阿拉尼亚与锡诺普，使罗姆苏丹国同时拥有地中海与黑海出口，商队税与过境贸易收入大增。", "source": "塞尔柱建筑铭文与瓦克夫文书"}, {"year": 1243, "headline": "克塞山之战：苏丹国臣属蒙古", "site": "克塞山", "coord": [38.6, 40.05], "detail": "蒙古将领拜住（Baiju）在克塞山之战击溃罗姆苏丹凯霍斯鲁二世，罗姆苏丹国成为蒙古（伊儿汗国）的藩属。安纳托利亚进入蒙古宗主权+突厥贝伊国的双轨时代，塞尔柱财富被征税抽走。", "source": "《剑桥土耳其史》卷 i"}], "settlements": [{"ancient": "科尼亚（伊科尼翁）", "modern": "科尼亚", "coord": [32.49, 37.87], "isCapital": true, "remark": "罗姆苏丹国都城，鲁米陵墓", "source": "Cahen《奥斯曼以前土耳其的史前史》/《剑桥土耳其史》"}, {"ancient": "锡瓦斯", "modern": "锡瓦斯", "coord": [37.02, 39.75], "isCapital": false, "remark": "丹麦门德王朝都城", "source": "《剑桥土耳其史》/ Evliya Çelebi《游记》"}, {"ancient": "尼西亚", "modern": "伊兹尼克", "coord": [29.72, 40.43], "isCapital": false, "remark": "1097—1261 尼西亚帝国都城", "source": "Akropolites《编年史》/ TIB"}, {"ancient": "特拉比松", "modern": "特拉布宗", "coord": [39.72, 41.0], "isCapital": false, "remark": "1204 年特拉比松帝国建立", "source": "Ostrogorsky / Bryer《特拉比松帝国》"}, {"ancient": "开塞利", "modern": "开塞利", "coord": [35.49, 38.73], "isCapital": false, "source": "Cahen《奥斯曼以前土耳其的史前史》/《剑桥土耳其史》"}, {"ancient": "阿拉尼亚", "modern": "阿拉尼亚", "coord": [32.0, 36.54], "isCapital": false, "remark": "基利杰阿尔斯兰二世夏宫", "source": "Cahen《奥斯曼以前土耳其的史前史》/《剑桥土耳其史》"}, {"ancient": "狄夫里吉", "modern": "迪夫里伊", "coord": [38.11, 39.37], "isCapital": false, "remark": "1228 年大清真寺与医院，世界遗产", "source": "Cahen《奥斯曼以前土耳其的史前史》/《剑桥土耳其史》"}, {"ancient": "开罗", "modern": "开罗（埃及）", "coord": [31.24, 30.04], "remark": "969 年法蒂玛建城，1171 年后阿尤布都城", "source": "《剑桥埃及史》/ Ibn Iyas《历代奇事》"}, {"ancient": "大马士革", "modern": "大马士革（叙利亚）", "coord": [36.29, 33.51], "remark": "赞吉与阿尤布王朝的叙利亚中枢", "source": "《剑桥伊斯兰史》卷 1 / Ibn ʿAsākir《大马士革史》"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.23, 31.78], "remark": "1099 年十字军攻陷，1187 年萨拉丁收复", "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}, {"ancient": "阿勒颇", "modern": "阿勒颇（叙利亚）", "coord": [37.16, 36.2], "remark": "赞吉王朝重镇，与十字军反复易手", "source": "《剑桥伊斯兰史》卷 1 / Ibn al-ʿAdim"}]},
  {"key": "mongol", "title": "蒙古宗主权", "badge": "伊儿汗", "fromYear": 1243, "toYear": 1300, "focusYear": 1275, "tint": "#7a5a8a", "seat": "科尼亚（藩属）· 大不里士", "summary": "1243 年克塞山之战后罗姆苏丹国成为蒙古（伊儿汗国）藩属，1277 年巴赫里马木留克介入、1279 年后苏丹国分裂。土库曼诸贝伊国（卡拉曼、格尔米扬、艾登、门泰塞、奥斯曼、萨鲁汗、卡雷西）在西部和中部兴起；东部有特拉比松帝国与奇里乞亚亚美尼亚王国为蒙古-马木留克缓冲。", "sourceFiles": ["mongol"], "phases": [{"until": 1243, "snap": "s_kosedag", "overview": "1243 年 · 克塞山之战：罗姆苏丹国臣属蒙古，安纳托利亚进入伊儿汗国宗主权时代。"}, {"until": 1277, "snap": "s_ilkhanid_direct", "overview": "1277 年 · 伊儿汗国直辖：马木留克介入安纳托利亚，蒙古直接征税，经济与人口承压。"}, {"until": 1300, "snap": "s_beyliks", "overview": "1300 年 · 诸贝伊国时代：奥斯曼、卡拉曼、格尔米扬、艾登等贝伊国在蒙古宗主权下并起。"}], "milestones": [{"year": 1243, "headline": "克塞山之战后罗姆苏丹国成为伊儿汗国藩属", "site": "克塞山", "coord": [38.6, 40.05], "detail": "克塞山之战后，罗姆苏丹国的外交、军事与征税权均受伊儿汗监督，苏丹由蒙古册立。1260/1277 年马木留克反攻与蒙古内乱使安纳托利亚成为代理战场。", "source": "Peacock《大塞尔柱帝国》"}, {"year": 1244, "headline": "伊儿汗国设罗姆行省", "site": "科尼亚", "coord": [32.49, 37.87], "detail": "蒙古在安纳托利亚设罗姆行省，派驻达鲁花赤与书记官，直接征收牧税、商税与户口调查，塞尔柱苏丹沦为税收承包人。", "source": "伊儿汗国文书"}, {"year": 1261, "headline": "尼西亚光复与东方困局", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "尼西亚帝国收复君士坦丁堡，但安纳托利亚的蒙古宗主权与贝伊国割据已成定局，拜占庭再也无力恢复东方领土。", "source": "Akropolites / 拜占庭史料"}, {"year": 1277, "headline": "马木留克苏丹拜巴尔斯介入安纳托利亚", "site": "埃尔比斯坦", "coord": [37.2, 38.2], "detail": "马木留克苏丹拜巴尔斯在埃尔比斯坦击败蒙古军，短暂介入安纳托利亚；此后蒙古加重税赋与行政直辖，土库曼贝伊与游牧部众向西北边境迁移，奥斯曼等贝伊国由此成形。", "source": "拜巴尔斯传 / 伊儿汗史料"}, {"year": 1280, "headline": "伊儿汗国的货币与税册统一", "site": "大不里士", "coord": [46.29, 38.07], "detail": "伊儿汗国统一银币（dirham）与税册，安纳托利亚的货币、度量衡与征税周期被纳入蒙古体系，商路秩序短期改善。", "source": "伊儿汗国文书"}, {"year": 1295, "headline": "加赞汗改宗伊斯兰教", "site": "大不里士", "coord": [46.29, 38.07], "detail": "伊儿汗国加赞汗改宗伊斯兰教并改革税制，安纳托利亚的蒙古统治者随之穆斯林化，与突厥贝伊国的文化隔阂缩小，也为伊儿汗国带来短暂复兴。", "source": "拉施特《史集》"}, {"year": 1299, "headline": "奥斯曼一世在瑟于特建立贝伊国", "site": "瑟于特", "coord": [30.18, 40.02], "detail": "奥斯曼一世（Osman Gazi）在瑟于特（Söğüt）一带建立自己的贝伊国，处拜占庭与蒙古势力的夹缝。此后数十年它以联姻、雇佣与吸收流亡为手段向比提尼亚扩张。", "source": "奥斯曼早期编年史"}, {"year": 1300, "headline": "安纳托利亚诸贝伊国并立", "site": "卡拉曼", "coord": [33.22, 37.18], "detail": "安纳托利亚进入「诸贝伊国」并立时期：卡拉曼、格尔米扬、艾登、门泰塞、萨鲁汗、卡雷西、奥斯曼等在蒙古宗主权下各自为政，也共享突厥-拜占庭边境的掠夺经济。", "source": "Zachariadou 关于贝伊国的研究"}], "settlements": [{"ancient": "科尼亚", "modern": "科尼亚", "coord": [32.49, 37.87], "isCapital": false, "remark": "苏丹国旧都，蒙古宗主权下", "source": "Ibn Bibi《塞尔柱史》/ Cahen"}, {"ancient": "卡拉曼", "modern": "卡拉曼", "coord": [33.22, 37.18], "isCapital": false, "remark": "卡拉曼贝伊国都城", "source": "拉施特《史集》/《剑桥伊朗史》卷 5"}, {"ancient": "瑟于特", "modern": "瑟于特", "coord": [30.18, 40.02], "isCapital": false, "remark": "奥斯曼贝伊国发源地", "source": "拉施特《史集》/《剑桥伊朗史》卷 5"}, {"ancient": "屈塔希亚", "modern": "屈塔希亚", "coord": [29.98, 39.42], "isCapital": false, "remark": "格尔米扬贝伊国都城", "source": "拉施特《史集》/《剑桥伊朗史》卷 5"}, {"ancient": "比尔吉", "modern": "比尔吉", "coord": [27.28, 38.31], "isCapital": false, "remark": "艾登贝伊国都城", "source": "拉施特《史集》/《剑桥伊朗史》卷 5"}, {"ancient": "大不里士", "modern": "大不里士", "coord": [46.29, 38.07], "isCapital": false, "remark": "伊儿汗国都城", "source": "拉施特《史集》/《剑桥伊朗史》卷 5"}, {"ancient": "锡瓦斯", "modern": "锡瓦斯", "coord": [37.02, 39.75], "isCapital": false, "source": "《剑桥土耳其史》/ Evliya Çelebi《游记》"}, {"ancient": "开罗", "modern": "开罗（埃及）", "coord": [31.24, 30.04], "remark": "马木留克苏丹国首都，1260 年艾因贾鲁特阻击蒙古", "source": "《剑桥埃及史》/ Ibn Iyas《历代奇事》"}, {"ancient": "大马士革", "modern": "大马士革（叙利亚）", "coord": [36.29, 33.51], "remark": "马木留克叙利亚首府", "source": "《剑桥伊斯兰史》卷 1 / Ibn ʿAsākir《大马士革史》"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.23, 31.78], "remark": "1291 年阿卡陷落后十字军彻底退出黎凡特", "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}]},
  {"key": "beylik", "title": "贝伊国与奥斯曼崛起", "badge": "贝伊国", "fromYear": 1300, "toYear": 1453, "focusYear": 1402, "tint": "#a8452f", "seat": "布尔萨 · 埃迪尔内", "summary": "奥斯曼一世至穆拉德一世逐步吞并比提尼亚与色雷斯，1389 年科索沃、1396 年尼科波利斯；巴耶济德一世 1397—1402 年兼并中部诸贝伊国，却在 1402 年安卡拉之战败于帖木儿，贝伊国复立、帝国进入 1402—1413 年空位期。穆拉德二世与穆罕默德二世重新整合，1453 年攻陷君士坦丁堡。", "sourceFiles": ["beylik"], "phases": [{"until": 1390, "snap": "s_burhaneddin", "overview": "1390 年 · 贝伊国并立与布尔汉丁：帖木儿南下前夜：奥斯曼、卡拉曼、布尔汉丁与白羊诸势力在安纳托利亚并立。"}, {"until": 1402, "snap": "s_ankara_battle", "overview": "1402 年 · 安卡拉之战：帖木儿击败巴耶济德一世，奥斯曼进入十一年空位期，贝伊国复立。"}], "milestones": [{"year": 1326, "headline": "奥斯曼夺取布尔萨，定为都城", "site": "布尔萨", "coord": [29.06, 40.19], "detail": "奥斯曼之子奥尔汗夺下比提尼亚的布尔萨，定为都城，并铸币、立行会、建清真寺。这是奥斯曼从边陲公国转为「国家」的关键一步。", "source": "奥斯曼编年史 / 早期铭文"}, {"year": 1329, "headline": "佩莱卡农之战", "site": "佩莱卡农", "coord": [29.4, 40.8], "detail": "奥尔汗击败拜占庭摄政约翰六世，控制比提尼亚通道；拜占庭从此再无反击能力，只能以雇佣与联姻维持。", "source": "拜占庭史料（坎塔库泽努斯）"}, {"year": 1331, "headline": "奥尔汗铸币与行会制度", "site": "布尔萨", "coord": [29.06, 40.19], "detail": "奥尔汗首铸奥斯曼银币（akçe），扶植行会（ahi）并管制市场，标志奥斯曼从掠夺经济转向城市财政与常备行政。", "source": "早期奥斯曼铭文"}, {"year": 1354, "headline": "加里波利站稳脚跟", "site": "加里波利", "coord": [26.67, 40.42], "detail": "奥斯曼在加里波利移民驻军，向色雷斯扩张；巴尔干由此成为帝国重心，安纳托利亚反而成为后方。", "source": "奥斯曼编年史"}, {"year": 1361, "headline": "穆拉德一世取阿德里安堡（埃迪尔内）", "site": "埃迪尔内", "coord": [26.56, 41.68], "detail": "穆拉德一世夺取阿德里安堡（埃迪尔内）并迁都于此，把扩张方向转向巴尔干。安纳托利亚诸贝伊国由此被纳入奥斯曼的册封体系，色雷斯成为帝国的新核心。", "source": "奥斯曼编年史"}, {"year": 1366, "headline": "加里波利地震与奥斯曼占领", "site": "加里波利", "coord": [26.67, 40.42], "detail": "地震毁坏加里波利城墙，奥斯曼趁机占领，取得越过达达尼尔的第一个桥头堡，此后向巴尔干持续扩张。", "source": "拜占庭编年史"}, {"year": 1389, "headline": "科索沃之战，奥斯曼控制巴尔干", "site": "科索沃", "coord": [21.07, 42.72], "detail": "科索沃之战，穆拉德一世死于战场但奥斯曼军获胜，塞尔维亚诸侯称臣。此役确立了奥斯曼在巴尔干的支配地位，也让统治重心长期不在安纳托利亚。", "source": "奥斯曼/塞尔维亚史料"}, {"year": 1400, "headline": "帖木儿的安纳托利亚战役", "site": "锡瓦斯", "coord": [37.02, 39.75], "detail": "帖木儿攻掠锡瓦斯并屠守军，随后南下叙利亚击溃马木留克；安纳托利亚的贝伊国格局被重新洗牌，为安卡拉之战铺路。", "source": "帖木儿史料 / 伊本·阿拉布沙"}, {"year": 1402, "headline": "安卡拉之战：帖木儿击败巴耶济德一世，帝国进入空位期", "site": "安卡拉", "coord": [33.03, 40.24], "detail": "帖木儿在安卡拉之战击败并俘虏巴耶济德一世，此前被吞并的贝伊国复立。奥斯曼进入 1402—1413 年的「空位期」（大空位），直到穆罕默德一世重新统一。", "source": "奥斯曼编年史 / 帖木儿史料"}, {"year": 1453, "headline": "穆罕默德二世攻陷君士坦丁堡", "site": "君士坦丁堡", "coord": [28.98, 41.01], "detail": "穆罕默德二世以巨炮与运河绕行、陆路运船入金角湾，经 53 天围攻攻陷君士坦丁堡。拜占庭帝国灭亡，奥斯曼成为跨欧亚的帝国，圣索菲亚改为清真寺。", "source": "Kritovoulos / 奥斯曼史料"}], "settlements": [{"ancient": "布尔萨", "modern": "布尔萨", "coord": [29.06, 40.19], "isCapital": true, "remark": "奥斯曼首个正式都城", "source": "奥斯曼早期铭文 /《剑桥土耳其史》"}, {"ancient": "埃迪尔内", "modern": "埃迪尔内", "coord": [26.56, 41.68], "isCapital": true, "remark": "1369 年后欧洲侧都城", "source": "《剑桥土耳其史》/ 威尼斯档案"}, {"ancient": "君士坦丁堡", "modern": "伊斯坦布尔", "coord": [28.98, 41.01], "isCapital": true, "remark": "1453 年后帝国都城", "source": "《剑桥土耳其史》/ 威尼斯档案"}, {"ancient": "卡拉曼", "modern": "卡拉曼", "coord": [33.22, 37.18], "isCapital": false, "source": "《剑桥土耳其史》/ 威尼斯档案"}, {"ancient": "锡瓦斯", "modern": "锡瓦斯", "coord": [37.02, 39.75], "isCapital": false, "remark": "卡迪·布尔汉丁国都城", "source": "《剑桥土耳其史》/ Evliya Çelebi《游记》"}, {"ancient": "迪亚巴克尔", "modern": "迪亚巴克尔", "coord": [40.23, 37.91], "isCapital": false, "remark": "白羊王朝都城", "source": "《剑桥土耳其史》/ 威尼斯档案"}, {"ancient": "安卡拉", "modern": "安卡拉", "coord": [32.86, 39.93], "isCapital": false, "remark": "1402 年帖木儿战场", "source": "Zürcher《现代土耳其史》/ Evliya Çelebi"}]},
  {"key": "ottoman", "title": "奥斯曼帝国鼎盛", "badge": "奥斯曼", "fromYear": 1453, "toYear": 1683, "focusYear": 1566, "tint": "#a8452f", "seat": "伊斯坦布尔", "summary": "1453 年穆罕默德二世取君士坦丁堡，1514 年查尔迪兰之战胜萨法维、1516—1517 年灭马木留克取叙利亚埃及，苏莱曼一世 1529 年围维也纳、1538 年普雷韦扎海战。帝国行省（eyalet）与桑贾克（sancak）制覆盖安纳托利亚与鲁米利亚；1683 年维也纳战败标志扩张终结。", "sourceFiles": ["ottoman"], "phases": [{"until": 1453, "snap": "s_conquest", "overview": "1453 年 · 攻陷君士坦丁堡：穆罕默德二世终结拜占庭，奥斯曼成为跨欧亚帝国。"}, {"until": 1480, "snap": "s_mehmed_late", "overview": "1480 年 · 穆罕默德二世晚年：夺取黑海与爱琴海诸岛，行省（eyalet）制度在安纳托利亚铺开。"}, {"until": 1517, "snap": "s_selim_conquests", "overview": "1517 年 · 塞利姆一世东征：查尔迪兰击败萨法维，灭马木留克取叙利亚与埃及。"}, {"until": 1566, "snap": "s_suleiman_era", "overview": "1566 年 · 苏莱曼时代：帝国鼎盛：贝尔格莱德、罗得岛、巴格达与北非入版图。"}, {"until": 1600, "snap": "s_celali", "overview": "1600 年 · 杰拉里叛乱年代：小冰期歉收、人口压力与地方武装，安纳托利亚乡村动荡。"}], "milestones": [{"year": 1453, "headline": "攻陷君士坦丁堡，拜占庭帝国终结", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "攻陷君士坦丁堡后，穆罕默德二世自称「恺撒」，恢复东正教牧首制以统御基督徒，并把安纳托利亚的旧贝伊国整编为行省（eyalet）与桑贾克。伊斯坦布尔成为欧亚商业枢纽。", "source": "《剑桥土耳其史》"}, {"year": 1461, "headline": "特拉比松帝国灭亡", "site": "特拉布宗", "coord": [39.72, 41.0], "detail": "穆罕默德二世吞并特拉比松帝国，黑海南岸归入奥斯曼，黑海成为「内湖」，热那亚与威尼斯的黑海殖民地随之终结。", "source": "Kritovoulos《穆罕默德二世史》"}, {"year": 1475, "headline": "夺取卡法与黑海贸易", "site": "锡诺普", "coord": [35.15, 42.03], "detail": "奥斯曼夺取热那亚在黑海的据点卡法，把黑海贸易与克里米亚汗国纳入体系，安纳托利亚北岸港口因此受益。", "source": "奥斯曼档案"}, {"year": 1492, "headline": "塞法迪犹太人迁入", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "西班牙驱逐令后大批塞法迪犹太人迁入奥斯曼，定居伊斯坦布尔、伊兹密尔与萨洛尼卡，带来印刷术、金融与巴尔干贸易网络。", "source": "奥斯曼档案研究"}, {"year": 1514, "headline": "查尔迪兰之战：塞利姆一世击败萨法维", "site": "查尔迪兰", "coord": [44.09, 39.19], "detail": "查尔迪兰之战，塞利姆一世以火炮与火枪击败萨法维沙阿伊斯玛仪，控制东西商路与库尔德斯坦。此役确立了逊尼派奥斯曼对什叶派萨法维的东部均势。", "source": "奥斯曼编年史 / 萨法维史料"}, {"year": 1517, "headline": "灭马木留克，取叙利亚与埃及", "site": "开罗", "coord": [31.24, 30.04], "detail": "塞利姆一世南下击败马木留克，取叙利亚、埃及与希贾兹，并取得麦加谢里夫的效忠与「哈里发」名分。帝国由此获得伊斯兰圣地的监护权与红海贸易。", "source": "奥斯曼编年史"}, {"year": 1529, "headline": "苏莱曼一世首次围攻维也纳", "site": "维也纳", "coord": [16.37, 48.21], "detail": "苏莱曼一世首次围攻维也纳未克，但已把匈牙利中部纳入附庸。中欧由此形成奥斯曼与哈布斯堡长达两百年的对峙线，安纳托利亚成为帝国兵源与粮仓。", "source": "《剑桥土耳其史》"}, {"year": 1555, "headline": "《阿马西亚和约》", "site": "阿马西亚", "coord": [35.83, 40.65], "detail": "奥斯曼与萨法维划定东部边界，战线稳定数十年；安纳托利亚东部得以恢复农业与商路，凡城与埃尔祖鲁姆重新繁荣。", "source": "奥斯曼/萨法维史料"}, {"year": 1571, "headline": "勒班陀海战：奥斯曼舰队受挫", "site": "勒班陀", "coord": [21.42, 38.42], "detail": "勒班陀海战，神圣同盟舰队击溃奥斯曼海军，但帝国在一年内重建舰队。此役象征地中海霸权转向，奥斯曼转向印度洋与北非战略。", "source": "奥斯曼/威尼斯史料"}, {"year": 1580, "headline": "白银流入与「大逃亡」", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "美洲白银流入引发物价革命，奥斯曼财政失衡，安纳托利亚出现农民弃田逃亡（Büyük Kaçgun），土地荒废与杰拉里叛乱随之而来。", "source": "《剑桥土耳其史》"}, {"year": 1638, "headline": "穆拉德四世的巴格达远征", "site": "巴格达", "coord": [44.4, 33.31], "detail": "穆拉德四世重夺巴格达，暂时稳住东方边疆；但十七世纪的安纳托利亚经历杰拉里叛乱、人口下降与税制崩坏，乡村经济长期低迷。", "source": "《剑桥土耳其史》"}], "settlements": [{"ancient": "伊斯坦布尔", "modern": "伊斯坦布尔", "coord": [28.98, 41.01], "isCapital": true, "source": "Zürcher / TDV《伊斯兰百科全书》（DİA）"}, {"ancient": "埃迪尔内", "modern": "埃迪尔内", "coord": [26.56, 41.68], "isCapital": false, "remark": "夏都与巴尔干门户", "source": "TDV《伊斯兰百科全书》(DİA) / Evliya Çelebi《游记》"}, {"ancient": "布尔萨", "modern": "布尔萨", "coord": [29.06, 40.19], "isCapital": false, "source": "奥斯曼早期铭文 /《剑桥土耳其史》"}, {"ancient": "阿勒颇", "modern": "阿勒颇", "coord": [37.16, 36.2], "isCapital": false, "remark": "帝国第三大城", "source": "《剑桥伊斯兰史》卷 1 / Ibn al-ʿAdim"}, {"ancient": "大马士革", "modern": "大马士革", "coord": [36.29, 33.51], "isCapital": false, "source": "《剑桥伊斯兰史》卷 1 / Ibn ʿAsākir《大马士革史》"}, {"ancient": "开罗", "modern": "开罗", "coord": [31.24, 30.04], "isCapital": false, "remark": "埃及行省首府", "source": "《剑桥埃及史》/ Ibn Iyas《历代奇事》"}, {"ancient": "特拉布宗", "modern": "特拉布宗", "coord": [39.72, 41.0], "isCapital": false, "remark": "1461 年并入奥斯曼", "source": "TDV《伊斯兰百科全书》(DİA) / Evliya Çelebi《游记》"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.23, 31.78], "remark": "奥斯曼耶路撒冷桑贾克，苏莱曼重修城墙", "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}, {"ancient": "亚历山大港", "modern": "亚历山大（埃及）", "coord": [29.92, 31.2], "remark": "奥斯曼海军基地，1798 年拿破仑登陆", "source": "Fraser《托勒密时期的亚历山大》"}]},
  {"key": "ottoman_late", "title": "奥斯曼晚期", "badge": "晚期奥斯曼", "fromYear": 1683, "toYear": 1922, "focusYear": 1880, "tint": "#a8452f", "seat": "伊斯坦布尔", "summary": "《卡尔洛维茨条约》(1699) 后帝国转入守势；1839—1876 年坦志麦特改革，1876 年《米德哈特宪法》，1908 年青年土耳其党革命。安纳托利亚成为帝国核心，1915 年亚美尼亚人大规模死亡事件至今争议；一战中 1915 年加里波利之战、1918 年《穆兹罗斯停战协定》、1920 年《色佛尔条约》被 1923 年《洛桑条约》取代。", "sourceFiles": ["ottoman_late"], "phases": [{"until": 1750, "snap": "s_ayan", "overview": "1750 年 · 地方显贵时代：地方显贵（ayan）以包税制掌握实权，中央对行省控制依赖合作。"}, {"until": 1839, "snap": "s_tanzimat", "overview": "1839 年 · 坦志麦特改革：《花厅御诏》启动近代化改革，行省制重整。"}, {"until": 1900, "snap": "s_hamidian", "overview": "1900 年 · 哈米德时代末期：铁路铺入安纳托利亚内陆，城市改造与近代行政推行。"}, {"until": 1918, "snap": "s_wwi_end", "overview": "1918 年 · 一战结束：穆兹罗斯停战，帝国解体；安纳托利亚成为民族斗争战场。"}], "milestones": [{"year": 1699, "headline": "《卡尔洛维茨条约》：奥斯曼首次大规模割地", "site": "卡尔洛维茨", "coord": [19.93, 45.2], "detail": "《卡尔洛维茨条约》结束大土耳其战争，奥斯曼首次大规模割地：匈牙利、特兰西瓦尼亚、亚速与部分摩里亚让出。帝国转入守势，安纳托利亚成为核心区与税基。", "source": "《剑桥土耳其史》"}, {"year": 1730, "headline": "郁金香时代的终结", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "帕特罗纳·哈利勒起义推翻郁金香时代的宫廷文化，艾哈迈德三世退位；此后的改革在保守派与改革派之间反复摆荡。", "source": "《剑桥土耳其史》"}, {"year": 1789, "headline": "塞利姆三世的「新秩序」", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "塞利姆三世推行新军（Nizam-ı Cedid）与常驻大使馆，被保守派推翻；但「改革—反扑—再改革」的循环由此定型。", "source": "Zürcher"}, {"year": 1826, "headline": "消灭近卫军（吉祥事变）", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "马哈茂德二世炮轰近卫军营，废除这支延续四百余年、屡次废立苏丹的旧军，建立近代化新军与中央集权的行省体系。", "source": "Zürcher《现代土耳其史》"}, {"year": 1839, "headline": "《花厅御诏》开启坦志麦特改革", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "《花厅御诏》宣布保障全体臣民的生命财产、废除包税、建立常备军与近代行政。坦志麦特改革开启，安纳托利亚的行省制（vilayet）与土地制度随之重组。", "source": "Zürcher《现代土耳其史》"}, {"year": 1856, "headline": "《巴黎条约》与改革诏书", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "克里米亚战争后奥斯曼被纳入欧洲协调体系，《哈蒂-胡马云诏书》承诺宗教平等与改革，但引发保守派与地方势力抵制，成为「东方问题」的一部分。", "source": "Zürcher / 条约文本"}, {"year": 1863, "headline": "奥斯曼银行与公共债务", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "设立奥斯曼银行（后为帝国银行）与公共债务管理署，欧洲资本进入安纳托利亚的铁路、港口与矿业，财政主权逐步外移。", "source": "Zürcher"}, {"year": 1876, "headline": "《米德哈特宪法》颁布，首次立宪", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "《米德哈特宪法》颁布，确立两院制议会与臣民权利，是伊斯兰世界第一部成文宪法。但苏丹阿卜杜勒哈米德二世在 1878 年即中止其效力。", "source": "Zürcher / 宪法文本"}, {"year": 1896, "headline": "安纳托利亚铁路通车", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "伊斯坦布尔—安卡拉铁路通车，内陆城市与港口连成一体，安纳托利亚的经济地理与行政中心由此重写。", "source": "Zürcher"}, {"year": 1908, "headline": "青年土耳其党革命", "site": "伊斯坦布尔", "coord": [28.98, 41.01], "detail": "青年土耳其党在萨洛尼卡起事，迫使苏丹恢复 1876 年宪法，开启第二立宪时期；政治重心从宫廷转向政党与军队。", "source": "Zürcher"}, {"year": 1913, "headline": "巴尔干战争与穆斯林难民潮", "site": "埃迪尔内", "coord": [26.56, 41.68], "detail": "巴尔干战争后数十万穆斯林难民涌入安纳托利亚，改变人口与土地结构，也为后来的民族政治与人口交换埋下伏笔。", "source": "Zürcher"}, {"year": 1915, "headline": "加里波利之战：奥斯曼击退协约国登陆", "site": "加里波利", "coord": [26.3, 40.24], "detail": "加里波利（恰纳卡莱）之战，奥斯曼军在穆斯塔法·凯末尔指挥下击退英法协约国登陆，粉碎了打通海峡的战略。此役使凯末尔成为民族英雄，也推迟了帝国解体。", "source": "《一战中的奥斯曼帝国》"}, {"year": 1920, "headline": "《色佛尔条约》签署，被 1923 年《洛桑条约》取代", "site": "塞夫勒", "coord": [2.22, 48.8], "detail": "《色佛尔条约》把安纳托利亚瓜分为希腊、意大利、法国势力范围与库尔德、亚美尼亚区。凯末尔领导的安卡拉政府在民族战争中逆转局势，最终以 1923 年《洛桑条约》取代之。", "source": "Zürcher / 条约文本"}], "settlements": [{"ancient": "伊斯坦布尔", "modern": "伊斯坦布尔", "coord": [28.98, 41.01], "isCapital": true, "source": "Zürcher / TDV《伊斯兰百科全书》（DİA）"}, {"ancient": "伊兹密尔", "modern": "伊兹密尔", "coord": [27.14, 38.42], "isCapital": false, "remark": "爱琴海贸易口岸", "source": "Zürcher《现代土耳其史》"}, {"ancient": "阿达纳", "modern": "阿达纳", "coord": [35.32, 37.0], "isCapital": false, "source": "Zürcher《现代土耳其史》"}, {"ancient": "萨洛尼卡", "modern": "塞萨洛尼基", "coord": [22.94, 40.64], "isCapital": false, "remark": "凯末尔出生地", "source": "Zürcher《现代土耳其史》"}, {"ancient": "的黎波里", "modern": "的黎波里（黎巴嫩）", "coord": [35.84, 34.44], "isCapital": false, "source": "Zürcher《现代土耳其史》"}, {"ancient": "巴格达", "modern": "巴格达", "coord": [44.4, 33.31], "isCapital": false, "remark": "1917 年被英军占领", "source": "Zürcher《现代土耳其史》"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.21, 31.77], "isCapital": false, "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}, {"ancient": "开罗", "modern": "开罗（埃及）", "coord": [31.24, 30.04], "remark": "1805 年穆罕默德·阿里自立，名义仍属奥斯曼", "source": "《剑桥埃及史》/ Ibn Iyas《历代奇事》"}, {"ancient": "苏伊士", "modern": "苏伊士（埃及）", "coord": [32.55, 29.97], "remark": "1869 年运河通航，帝国近东地位受制于英法", "source": "Zürcher《现代土耳其史》"}, {"ancient": "大马士革", "modern": "大马士革（叙利亚）", "coord": [36.29, 33.51], "remark": "1918 年费萨尔在此宣布阿拉伯王国", "source": "《剑桥伊斯兰史》卷 1 / Ibn ʿAsākir《大马士革史》"}]},
  {"key": "republic", "title": "土耳其共和国", "badge": "共和国", "fromYear": 1923, "toYear": 2026, "focusYear": 1938, "tint": "#a8452f", "seat": "安卡拉", "summary": "1923 年 10 月 29 日共和国成立，凯末尔·阿塔图尔克推行世俗化、文字拉丁化（1928）、姓氏法与妇女参政权（1934）；1939 年并入哈塔伊。1945 年后多党制，1952 年入北约，1960/1971/1980 年三次军事政变，1983 年厄扎尔市场化改革，1999 年欧盟候选国，2002 年后正义与发展党长期执政，2017 年改行总统制。", "sourceFiles": ["republic"], "phases": [{"until": 1923, "snap": "s_republic_found", "overview": "1923 年 · 共和国成立：洛桑条约后土耳其共和国成立，定都安卡拉。"}, {"until": 1935, "snap": "s_ataturk_end", "overview": "1935 年 · 阿塔图尔克末年：文字拉丁化、姓氏法、国家主义经济；1938 年凯末尔逝世。"}, {"until": 1960, "snap": "s_cold_war", "overview": "1960 年 · 冷战年代：入北约、多党制与三次军事政变，安纳托利亚城市化加速。"}, {"until": 1970, "snap": "s_industrial", "overview": "1970 年 · 工业化与移民：计划经济与进口替代推进，向欧洲输出劳务移民。"}, {"until": 1990, "snap": "s_ozal", "overview": "1990 年 · 厄扎尔时代：市场化与私有化、欧盟申请，西南沿海城市与旅游业扩张。"}, {"until": 2010, "snap": "s_akp_mid", "overview": "2010 年 · 正发党中期：城市化与区域开发工程，叙利亚战争外溢与难民问题。"}, {"until": 2026, "snap": "s_present", "overview": "2026 年 · 当代土耳其：8500 万人口的 G20 经济体，欧盟候选国，安纳托利亚仍是文明交汇处。"}], "milestones": [{"year": 1923, "headline": "10 月 29 日土耳其共和国成立，定都安卡拉", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "1923 年 10 月 29 日，大国民议会宣布成立土耳其共和国，凯末尔当选首任总统，定都安卡拉。洛桑条约确认了土耳其的现代疆界，苏丹制与哈里发制先后被废除。", "source": "Zürcher"}, {"year": 1924, "headline": "废除哈里发制", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "大国民议会废除哈里发制、关闭宗教法庭与宗教学校，世俗化改革正式启动；这是伊斯兰世界第一次以国家法令终结哈里发制度。", "source": "Zürcher"}, {"year": 1928, "headline": "文字改革：以拉丁字母取代阿拉伯字母", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "土耳其以拉丁字母取代阿拉伯-波斯字母，配套推行国民教育与「语言改革」。此举大幅提高识字率，也造成与伊斯兰书写传统的断裂。", "source": "Zürcher / 改革文献"}, {"year": 1930, "headline": "女性获得市政选举权", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "1930 年女性获得市政选举权，1934 年获得全国选举权与被选举权，是同期欧洲较早实现的国家之一。", "source": "Zürcher"}, {"year": 1934, "headline": "妇女获得选举权与被选举权", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "妇女获得选举权与被选举权（早于法国、意大利等国），同时颁布姓氏法、废除旧称号。改革以国家主义、世俗化为纲，安纳托利亚社会结构剧烈变动。", "source": "Zürcher"}, {"year": 1939, "headline": "哈塔伊并入土耳其", "site": "安塔基亚", "coord": [36.16, 36.2], "detail": "哈塔伊（亚历山德勒塔）经公投并入土耳其，是共和国唯一一次领土扩张。该地区 1936 年后由法国托管叙利亚，二战后叙利亚长期不承认此举。", "source": "Zürcher / 国际联盟档案"}, {"year": 1946, "headline": "多党制的开端", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "民主党成立并在 1950 年大选中获胜，实现土耳其首次和平政权更替；此前二十余年由共和人民党一党执政。", "source": "Zürcher"}, {"year": 1952, "headline": "加入北约", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "土耳其加入北约，成为西方在黑海与中东之间的战略支点。朝鲜战争出兵换取成员资格，此后接受马歇尔计划援助并与美国建立军事同盟。", "source": "Zürcher"}, {"year": 1963, "headline": "《安卡拉协定》与欧共体", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "土耳其与欧共体签订《安卡拉协定》成为联系国，此后关税同盟与入盟进程构成其外交与经济政策的主轴。", "source": "欧盟文件"}, {"year": 1980, "headline": "第三次军事政变与 1982 年宪法", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "1980 年 9 月 12 日军方第三次政变，解散议会与政党，随后制定 1982 年宪法（至今仍部分有效）。政变带来长期的政治稳定，也强化了军方与中央集权。", "source": "Zürcher"}, {"year": 1984, "headline": "东南部的长期冲突", "site": "迪亚巴克尔", "coord": [40.23, 37.91], "detail": "PKK 开始武装行动，东南部进入长期冲突状态，村庄撤离与人口迁徙加剧区域发展失衡，成为共和国后期的核心议题。", "source": "学术研究与公开报告"}, {"year": 1999, "headline": "成为欧盟候选国", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "赫尔辛基峰会给予土耳其候选国地位，随后推行法治、军队文职化与少数文化权利改革，以开启入盟谈判。", "source": "欧盟理事会文件"}, {"year": 2016, "headline": "未遂政变与紧急状态", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "2016 年 7 月政变未遂后实施两年紧急状态，大规模清洗军警与公务员；2017 年公投改行总统制，政治体制发生根本变化。", "source": "国际观察报告 / Zürcher 修订版"}, {"year": 2023, "headline": "共和国百年", "site": "安卡拉", "coord": [32.86, 39.93], "detail": "2023 年土耳其迎来共和国百年，同年经历东南大地震与总统选举；区域差距、叙利亚难民与通胀仍是核心议题。", "source": "公开报告"}], "settlements": [{"ancient": "安卡拉", "modern": "安卡拉", "coord": [32.86, 39.93], "isCapital": true, "remark": "1923 年起共和国首都", "source": "Zürcher《现代土耳其史》/ Evliya Çelebi"}, {"ancient": "伊斯坦布尔", "modern": "伊斯坦布尔", "coord": [28.98, 41.01], "isCapital": false, "remark": "最大城市与经济中心", "source": "Zürcher / TDV《伊斯兰百科全书》（DİA）"}, {"ancient": "伊兹密尔", "modern": "伊兹密尔", "coord": [27.14, 38.42], "isCapital": false, "source": "Zürcher《现代土耳其史》"}, {"ancient": "加济安泰普", "modern": "加济安泰普", "coord": [37.38, 37.07], "isCapital": false, "source": "Zürcher《现代土耳其史》"}, {"ancient": "迪亚巴克尔", "modern": "迪亚巴克尔", "coord": [40.23, 37.91], "isCapital": false, "remark": "东南部库尔德地区中心", "source": "Zürcher《现代土耳其史》"}, {"ancient": "特拉布宗", "modern": "特拉布宗", "coord": [39.72, 41.0], "isCapital": false, "source": "Zürcher《现代土耳其史》"}, {"ancient": "安塔基亚", "modern": "安塔基亚", "coord": [36.16, 36.2], "isCapital": false, "remark": "1939 年并入", "source": "Zürcher《现代土耳其史》"}, {"ancient": "开罗", "modern": "开罗（埃及）", "coord": [31.24, 30.04], "remark": "1952 年自由军官革命，地区政治重心之一", "source": "《剑桥埃及史》/ Ibn Iyas《历代奇事》"}, {"ancient": "大马士革", "modern": "大马士革（叙利亚）", "coord": [36.29, 33.51], "remark": "叙利亚内战与外溢的主要受影响城市", "source": "《剑桥伊斯兰史》卷 1 / Ibn ʿAsākir《大马士革史》"}, {"ancient": "耶路撒冷", "modern": "耶路撒冷", "coord": [35.23, 31.78], "remark": "巴以问题的核心地点", "source": "约瑟夫斯《犹太战记》/《新编考古百科全书》"}]}
];

